#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""NSF local: corte IR y energía máxima como entradas; historial acumulativo.

Instalar: python -m pip install numpy scipy matplotlib mpmath
Ejecutar desde una terminal (Windows, Linux o macOS):
  python graficos_nsf_local.py
  python graficos_nsf_local.py --ir 1e-8 --emax 2024
  python graficos_nsf_local.py --ir 1e-8 --emax 4048
  python graficos_nsf_local.py --solo-graficos
  python graficos_nsf_local.py --help

Ei=G=epsilon=1. Las entradas son kappa_IR/Ei y Emax/Ei (>16).
Incluye los 14 cortes IR ya calculados y el control Emax/Ei=4048.
Cada cálculo nuevo se guarda y se incorpora a su curva de Emax.
Los puntos conocidos se reutilizan; --recalcular fuerza una nueva evaluación.
El método por defecto usa ocho réplicas independientes por región, orden16,
malla polar refinada y controles angulares/radiales. No impone una delta
externa de conservación de energía. Solo incluye los canales iterados 22 y23.

Motor Python incluido en este archivo. No descarga fuentes ni necesita
compilador, DLL, ZIP ni archivos de otra sesión. Ver LEEME_NSF_LOCAL.txt.
"""
import argparse
import concurrent.futures as cf
import csv
import hashlib
import json
import math
import multiprocessing as mp
import os
from pathlib import Path
import sys
import time

for _thread_var in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS']:
    os.environ[_thread_var]='1'
try:
    import numpy as np
    import mpmath
    import matplotlib
    from scipy.stats import qmc
except ImportError as exc:
    raise SystemExit('Faltan bibliotecas. Ejecutá: python -m pip install numpy scipy matplotlib mpmath') from exc

VERSION='NSF-IR-local-history-2.0'
_MODEL=None


def atomic_json(path,value):
    tmp=path.with_suffix(path.suffix+'.tmp')
    tmp.write_text(json.dumps(value,indent=2,allow_nan=False),encoding='utf-8')
    os.replace(tmp,path)


def install_engine(out):
    digest=hashlib.sha256(json.dumps(ENGINE_SOURCES,sort_keys=True).encode()).hexdigest()
    root=out/('_motor_nsf_'+digest[:12])
    for name,source in ENGINE_SOURCES.items():
        path=root/name;path.parent.mkdir(parents=True,exist_ok=True)
        if path.exists():
            if path.read_text(encoding='utf-8')!=source:
                raise RuntimeError(f'El motor local fue editado: {path}. Usá otra --salida para extraer una copia limpia.')
        else:path.write_text(source,encoding='utf-8')
    return root,digest


def init_worker(root):
    global _MODEL
    sys.path.insert(0,str(Path(root)/'precision23'));sys.path.insert(0,str(root))
    os.environ['FUSED_INTEGRAND']='0'
    import modelo_local
    _MODEL=modelo_local


def task_worker(task):
    kind,payload=task
    return _MODEL.evaluate23(payload) if kind=='23' else _MODEL.evaluate22(payload)


def read_ledger(path):
    if not path.exists():return []
    data=path.read_bytes();parts=data.splitlines(keepends=True);rows=[];valid=0
    for i,line in enumerate(parts):
        try:row=json.loads(line)
        except (ValueError,UnicodeDecodeError):
            if i==len(parts)-1 and not line.endswith(b'\n'):
                with path.open('r+b') as stream:stream.truncate(valid)
                print(f'Reanudación: se descartó solo la última línea incompleta de {path.name}.',flush=True)
                break
            raise RuntimeError(f'Archivo de avance corrupto: {path}, línea {i+1}')
        rows.append(row);valid+=len(line)
    if rows and valid==len(data) and not data.endswith(b'\n'):
        with path.open('ab') as stream:stream.write(b'\n')
    ids=[r['id'] for r in rows]
    if len(ids)!=len(set(ids)):raise RuntimeError(f'Hay muestras duplicadas en {path}')
    return rows


def cached_stage(pool,path,tasks,stage,workers):
    """Guarda cada muestra; solo omite IDs ya terminados. Cola limitada."""
    rows=read_ledger(path);done={r['id'] for r in rows};expected={t[0] for t in tasks}
    if len(expected)!=len(tasks):raise RuntimeError('IDs de tarea duplicados')
    if not done<=expected:raise RuntimeError(f'El avance no corresponde a esta configuración: {path}')
    todo=iter((key,task) for key,task in tasks if key not in done)
    left=len(tasks)-len(done)
    print(f'  {stage}: {len(done)}/{len(tasks)} guardadas; faltan {left}.',flush=True)
    pending={};started=time.monotonic();count=0
    with path.open('a',encoding='utf-8') as stream:
        def submit_one():
            try:key,task=next(todo)
            except StopIteration:return False
            pending[pool.submit(task_worker,task)]=key;return True
        for _ in range(max(1,2*workers)):submit_one()
        try:
            while pending:
                ready,_=cf.wait(pending,return_when=cf.FIRST_COMPLETED)
                for future in ready:
                    key=pending.pop(future)
                    try:row=future.result()
                    except Exception as exc:
                        raise RuntimeError(f'Falló {stage}, muestra {key}. Los datos anteriores están guardados. No se reemplazan errores por ceros.') from exc
                    if row['id']!=key:raise RuntimeError('La muestra devolvió un ID inesperado')
                    stream.write(json.dumps(row,allow_nan=False)+'\n');stream.flush();rows.append(row);count+=1
                    if count%64==0 or count==left:
                        print(f'    {count}/{left} nuevas, {time.monotonic()-started:.0f} s',flush=True)
                    submit_one()
        except BaseException:
            for future in pending:future.cancel()
            raise
    if len(rows)!=len(tasks):raise RuntimeError(f'Etapa incompleta: {stage}')
    return sorted(rows,key=lambda r:r['id'])


def replica_seed(cut,band,rep,master):
    if cut==1e-5 and master==20261017:
        anchors={'low':[410003,420007,430009,440011],'uv':[510013,520019,530021,540031]}
        if rep<4:return anchors[band][rep]
    token=f'{master}:{float(cut).hex()}:{band}:{rep}'.encode()
    return int.from_bytes(hashlib.sha256(token).digest()[:4],'little')


def base_tasks(cut,cfg):
    out=[]
    for band,power in [('low',cfg['power_low']),('uv',cfg['power_uv'])]:
        for rep in range(cfg['replicas']):
            seed=replica_seed(cut,band,rep,cfg['seed'])
            points=qmc.Sobol(5,scramble=True,seed=seed).random_base2(power)
            for i,u in enumerate(points):
                key=f'{band}:{seed}:{i}'
                out.append((key,('23',(cut,cfg['emax'],band,u.tolist(),cfg['base_order'],i,seed,False))))
    return out






def combined_summary(cut,cfg,rows22,vector23,cov23):
    I22=math.fsum(r['P'] for r in rows22);D22=math.fsum(r['D'] for r in rows22);I23,D23=map(float,vector23)
    if min(I22,I23)<=0:raise RuntimeError('Estimación de probabilidad no positiva. Aumentá el muestreo; no se guarda un promedio no físico.')
    factor=cfg['epsilon']**2;total=I22+factor*I23;excess=D22+factor*D23;mean=1+excess/total;weight=factor*I23/total
    def se(g):
        g=np.array(g);return float(np.sqrt(max(0,g@cov23@g)))
    result=dict(kappa=cut,epsilon=cfg['epsilon'],Emax=cfg['emax'],I22=I22,D22=D22,Q22=I22+D22,I23=I23,D23=D23,Q23=I23+D23,covariance_ID=cov23.tolist(),mean22=1+D22/I22,mean23=1+D23/I23,mean23_MC_SE=se([-D23/I23**2,1/I23]),combined_mean=mean,combined_mean_MC_SE=se([-factor*excess/total**2,factor/total]),weight23=weight,weight23_MC_SE=se([factor*I22/total**2,0]),profile=cfg['profile'])
    if not min(result['mean22'],result['mean23'])-1e-12<=mean<=max(result['mean22'],result['mean23'])+1e-12:raise RuntimeError('El combinado no está entre ambos promedios')
    if not math.isclose(mean,(1-weight)*result['mean22']+weight*result['mean23'],abs_tol=1e-12):raise RuntimeError('Normalización inconsistente del combinado')
    return result








def energy_residuals(row,epsilon=1.):
    """Residuos adimensionales; Ei=1. Conserva la covarianza de I23 y D23."""
    I2=float(row.get('I22',row.get('I22_fixed')));I3=float(row['I23'])
    D2=float(row['D22']) if 'D22' in row else float(row.get('Q22',row.get('Q22_fixed')))-I2
    D3=float(row['D23']) if 'D23' in row else float(row['Q23'])-I3
    factor=epsilon**2;total=I2+factor*I3
    if min(I2,I3,total)<=0:raise ValueError('Los residuos requieren pesos positivos.')
    if 'covariance_ID' in row:cov=np.asarray(row['covariance_ID'],float)
    elif 'covariance_of_mean' in row:
        change=np.array([[1.,0.],[-1.,1.]])
        cov=change@np.asarray(row['covariance_of_mean'],float)@change.T
    else:cov=None
    def se(g,fallback):
        if cov is None:return float(row.get(fallback,0.))
        g=np.asarray(g,float);return float(np.sqrt(max(0,g@cov@g)))
    r2=D2/I2;r3=D3/I3;f3=factor*I3/total;c2=D2/total;c3=factor*D3/total
    result=dict(kappa=float(row['kappa']),r2=r2,r3=r3,
                r3_MC_SE=se([-D3/I3**2,1/I3],'mean23_MC_SE'),
                f3=f3,f3_MC_SE=se([factor*I2/total**2,0],'weight23_MC_SE'),
                c2=c2,c2_MC_SE=se([-factor*D2/total**2,0],'c2_MC_SE'),
                c3=c3,c3_MC_SE=se([-factor**2*D3/total**2,factor/total],'c3_MC_SE'),
                rE=c2+c3,rE_MC_SE=se([-factor*(D2+factor*D3)/total**2,factor/total],'combined_mean_MC_SE'))
    if not math.isclose(result['rE'],(1-f3)*r2+f3*r3,abs_tol=1e-12):
        raise RuntimeError('La identidad de residuos no se cumple.')
    return result






def _mean_plot_style():
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'serif','font.serif':['STIXGeneral'],'mathtext.fontset':'stix','font.size':10,'axes.labelsize':10,'axes.titlesize':11,'xtick.labelsize':9,'ytick.labelsize':9,'axes.spines.top':False,'axes.spines.right':False,'pdf.fonttype':42,'axes.linewidth':.7})






def _mean_axes(ax,rows):
    from matplotlib.ticker import LogLocator,NullFormatter,ScalarFormatter
    ax.set_xscale('log');ax.set_xlim(min(r['kappa'] for r in rows)*.7,max(.075,max(r['kappa'] for r in rows)*1.5))
    ax.xaxis.set_major_locator(LogLocator(base=10,numticks=8));ax.xaxis.set_minor_locator(LogLocator(base=10,subs=(2,5),numticks=12));ax.xaxis.set_minor_formatter(NullFormatter())
    ax.set_xlabel(r'Infrared cutoff $\kappa_{\rm IR}/E_i$');ax.grid(axis='y',color='.9',lw=.5)
    ax.tick_params(direction='in',which='both');ax.yaxis.set_major_formatter(ScalarFormatter(useOffset=False))








# Interfaz local: entradas libres, muestreo directo e historial persistente.
import contextlib
import datetime
import re
import uuid


def input_number(value):
    value=str(value).strip().replace(',', '.')
    power=re.fullmatch(r'10\s*(?:\^|\*\*)\s*([+-]?\d+)',value)
    try:
        number=10.**int(power.group(1)) if power else float(value)
    except (ValueError,OverflowError) as exc:
        raise argparse.ArgumentTypeError('Ingresá un número, por ejemplo 1e-8 o 2024.') from exc
    if not math.isfinite(number):raise argparse.ArgumentTypeError('El valor debe ser finito.')
    return number


@contextlib.contextmanager
def history_lock(out):
    """Una sola ejecución por carpeta; el sistema libera el bloqueo al salir."""
    stream=(out/'historial.lock').open('a+b')
    acquired=False
    try:
        stream.seek(0,2)
        if not stream.tell():stream.write(b'0');stream.flush()
        stream.seek(0)
        try:
            if os.name=='nt':
                import msvcrt
                msvcrt.locking(stream.fileno(),msvcrt.LK_NBLCK,1)
            else:
                import fcntl
                fcntl.flock(stream.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
            acquired=True
        except OSError as exc:
            raise RuntimeError('Ya hay otra ejecución usando esta carpeta. Esperá que termine o elegí otra --salida.') from exc
        yield
    finally:
        if acquired:
            stream.seek(0)
            if os.name=='nt':
                import msvcrt
                msvcrt.locking(stream.fileno(),msvcrt.LK_UNLCK,1)
            else:
                import fcntl
                fcntl.flock(stream.fileno(),fcntl.LOCK_UN)
        stream.close()


def point_equal(a,b):
    return all(math.isclose(float(a[k]),float(b[k]),rel_tol=1e-12,abs_tol=0) for k in ['kappa','Emax'])


def normalized_point(row,maximum=2024.):
    r=dict(row);r['kappa']=float(r['kappa']);r['Emax']=float(r.get('Emax',maximum))
    if float(r.get('epsilon',1.))!=1.:raise ValueError('Este historial usa epsilon=1; no se mezclan otros pesos perturbativos.')
    v=energy_residuals(r,1.)
    r.update(combined_mean=1+v['rE'],combined_mean_MC_SE=v['rE_MC_SE'],combined_residual=v['rE'],
             weight23=v['f3'],weight23_MC_SE=v['f3_MC_SE'])
    if not 0<r['kappa']<.5 or not r['Emax']>16:raise ValueError('Parámetros del resultado fuera del dominio admitido.')
    if not all(math.isfinite(r[k]) for k in ['combined_mean','combined_mean_MC_SE','weight23','weight23_MC_SE']):
        raise ValueError('El resultado contiene valores no finitos.')
    if r['combined_mean_MC_SE']<0 or not 0<=r['weight23']<=1:raise ValueError('Resultado no válido.')
    return r


def archived_points():
    source=REFERENCE_RESULTS['previous']+[REFERENCE_RESULTS['lowest']]+REFERENCE_RESULTS.get('intermediate',[])+REFERENCE_RESULTS.get('lower_ir',[])
    return [normalized_point(r) for r in source+REFERENCE_RESULTS.get('upper_cutoff_checks',[])]


def load_history(out):
    path=out/'historial_nsf.json'
    if path.exists():
        data=json.loads(path.read_text(encoding='utf-8'))
        if data.get('schema_version')!=1 or not isinstance(data.get('runs'),list):raise ValueError('Formato de historial no reconocido.')
    else:data={'schema_version':1,'units':{'Ei':1.,'G':1.,'epsilon':1.},'runs':[]}
    if data.get('legacy_migration_done'):return data
    # Incorpora una sola vez los resultados de versiones anteriores.
    known={r.get('legacy_source') for r in data['runs'] if r.get('legacy_source')}
    paths=([out/'resumen.json'] if (out/'resumen.json').exists() else [])
    if (out/'avance').exists():paths+=sorted((out/'avance').glob('*/k_*/resultado.json'))
    for path in paths:
        obj=json.loads(path.read_text(encoding='utf-8'))
        candidates=obj.get('results',[obj]);maximum=obj.get('config',{}).get('emax',2024.)
        for item in candidates:
            if 'kappa' not in item:continue
            tag=hashlib.sha256((str(path.resolve())+json.dumps(item,sort_keys=True)).encode()).hexdigest()
            if tag in known:continue
            point=normalized_point(item,maximum)
            data['runs'].append({'id':tag,'result':point,'origin':'imported_local','legacy_source':tag})
            known.add(tag)
    data['legacy_migration_done']=True
    return data


def active_points(history):
    points=archived_points()
    for run in history['runs']:
        r=normalized_point(run['result'])
        if r.get('validation_passed') is False:continue
        points=[p for p in points if not point_equal(p,r)];points.append(r)
    return sorted(points,key=lambda r:(r['Emax'],r['kappa']))


def append_result(history,result,cfg):
    history['runs'].append({'id':uuid.uuid4().hex,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
                            'origin':'local','config':dict(cfg),'result':normalized_point(result)})


def save_history(out,history):
    # El historial es la fuente de datos: se guarda antes de generar el gráfico.
    atomic_json(out/'historial_nsf.json',history)
    points=active_points(history)
    columns=['kappa','Emax','combined_mean','combined_mean_MC_SE','combined_residual','weight23','weight23_MC_SE','profile']
    with (out/'energia_media_combinada.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=columns,extrasaction='ignore');w.writeheader();w.writerows(points)
    plot_combined_history(out,points)


def plot_combined_history(out,points):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from matplotlib.ticker import LogLocator,NullFormatter,MaxNLocator,FuncFormatter
    _mean_plot_style()
    maxima=sorted({r['Emax'] for r in points});palette=['#2463a0','#7a4e92','#b45e1a','#777777','#ba6d99']
    colors={2024.:'#26745e',4048.:'#b33f32'}
    for e in maxima:
        if e not in colors:colors[e]=palette[(len(colors)-2)%len(palette)]
    fig,ax=plt.subplots(figsize=(7.3,4.8))
    def draw(target,rows,small=False):
        for e in maxima:
            group=[r for r in rows if r['Emax']==e]
            if not group:continue
            target.errorbar([r['kappa'] for r in group],[r['combined_mean'] for r in group],
                yerr=[r['combined_mean_MC_SE'] for r in group],fmt='o-',color=colors[e],mfc=colors[e],
                ms=3.5 if small else 4,lw=1. if small else 1.2,elinewidth=.7,capsize=2,
                label=rf'$E_{{\max}}={e:g}E_i$',zorder=3)
    draw(ax,points);ax.axhline(1,color='.45',ls=':',lw=.8)
    _mean_axes(ax,points);ax.set_title('Combined channels',loc='left',pad=8)
    ax.set_ylabel(r'Mean total outgoing energy $\langle E_f\rangle/E_i$')
    bottom=min(r['combined_mean']-2*r['combined_mean_MC_SE'] for r in points)
    top=max(r['combined_mean']+2*r['combined_mean_MC_SE'] for r in points)
    pad=max(.001,.08*(top-bottom))
    ax.set_ylim(min(.975,bottom-pad),max(1.0055,top+pad))
    ax.legend(loc='upper left',frameon=False,fontsize=9,ncol=2 if len(maxima)>4 else 1)
    small=[r for r in points if r['kappa']<=1.2e-5]
    if len({r['kappa'] for r in small})>=2:
        inset=ax.inset_axes([.14,.14,.44,.34]);draw(inset,small,True)
        inset.axhline(1,color='.5',ls=':',lw=.6);inset.set_xscale('log')
        inset.set_xlim(min(r['kappa'] for r in small)*.7,max(1.5e-5,max(r['kappa'] for r in small)*1.2))
        lo=min([1.]+[r['combined_mean']-2*r['combined_mean_MC_SE'] for r in small])
        hi=max([1.]+[r['combined_mean']+2*r['combined_mean_MC_SE'] for r in small]);span=max(hi-lo,1e-9)
        inset.set_ylim(lo-.04*span,hi+.12*span)
        inset.xaxis.set_major_locator(LogLocator(base=10,numticks=6));inset.xaxis.set_minor_formatter(NullFormatter())
        inset.yaxis.set_major_locator(MaxNLocator(3));inset.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{y:.5f}'))
        inset.tick_params(labelsize=7,direction='in');inset.set_title('Small infrared cutoffs',fontsize=8,pad=4)
        inset.grid(axis='y',color='.92',lw=.4)
    fig.subplots_adjust(left=.12,right=.98,bottom=.14,top=.91)
    fig.savefig(out/'energia_media_combinada_EN.pdf');fig.savefig(out/'energia_media_combinada_EN.png',dpi=240)
    plt.close(fig)


def reduce_direct23(rows,cfg):
    vector=np.zeros(2);cov=np.zeros((2,2));replicas={}
    for band,power in [('low',cfg['power_low']),('uv',cfg['power_uv'])]:
        seeds=sorted({r['seed'] for r in rows if r['band']==band})
        if len(seeds)!=cfg['replicas']:raise RuntimeError('Faltan réplicas completas en '+band)
        estimates=[];metadata=[];N=2**power
        for seed in seeds:
            rr=sorted((r for r in rows if r['band']==band and r['seed']==seed),key=lambda r:r['index'])
            if [r['index'] for r in rr]!=list(range(N)):raise RuntimeError('Réplica incompleta o duplicada.')
            value=[math.fsum(r['P'] for r in rr)/N,math.fsum((r['E']-1)*r['P'] for r in rr)/N]
            estimates.append(value);metadata.append({'seed':seed,'N':N,'estimate_ID':value})
        a=np.array(estimates);vector+=a.mean(0);cov+=np.cov(a,rowvar=False,ddof=1)/len(a);replicas[band]=metadata
    return vector,cov,replicas


def direct_controls(cut,cfg,rows,nodes22,rows22):
    selected={}
    for band in ['low','uv']:
        for seed in sorted({r['seed'] for r in rows if r['band']==band}):
            accepted=[r for r in rows if r['band']==band and r['seed']==seed and r['P']>0]
            if not accepted:raise RuntimeError('Réplica sin contribuciones aceptadas; aumentá el muestreo.')
            metrics=[lambda r:abs((r['E']-1)*r['P']),lambda r:(r['E']-1)**2*r['P']]
            if band=='low':metrics.append(lambda r:r['P'])
            for metric in metrics:
                r=max(accepted,key=metric);selected[r['id']]=r
    refs=[];tasks=[]
    for key,r in selected.items():
        refs.append({'id':key,'channel':'23','P':r['P']})
        tasks.append((key,('23',(cut,cfg['emax'],r['band'],r['u5'],2*cfg['target_order'],r['index'],r['seed'],True))))
    for index in sorted({max(rows22,key=lambda r:r['P'])['index'],max(rows22,key=lambda r:abs(r['D']))['index']}):
        r=next(r for r in rows22 if r['index']==index);payload=list(nodes22[index]);payload[2]=2*cfg['order22'];key=str(index)
        refs.append({'id':key,'channel':'22','P':r['P']});tasks.append((key,('22',payload)))
    return refs,tasks


def calculate_direct(cut,cfg,root,workdir,workers):
    workdir.mkdir(parents=True,exist_ok=True);path=workdir/'resultado.json'
    if path.exists():return json.loads(path.read_text(encoding='utf-8'))
    atomic_json(workdir/'configuracion.json',dict(cut=cut,**cfg))
    pool=cf.ProcessPoolExecutor(max_workers=workers,mp_context=mp.get_context('spawn'),initializer=init_worker,initargs=(str(root),));ok=False
    try:
        tasks=[]
        for key,(kind,payload) in base_tasks(cut,cfg):
            payload=list(payload);payload[4]=cfg['target_order'];payload[-1]=True;tasks.append((key,(kind,payload)))
        rows=cached_stage(pool,workdir/'muestras23_directas.jsonl',tasks,'2→3 directo',workers)
        init_worker(str(root));nodes=_MODEL.quadrature22(cut,cfg['emax'],cfg['order22'],cfg['ne22'],cfg['nq22'])
        rows22=cached_stage(pool,workdir/'cuadratura22.jsonl',[(str(t[-1]),('22',t)) for t in nodes],'2→2',workers)
        vector,cov,replicas=reduce_direct23(rows,cfg);result=combined_summary(cut,cfg,rows22,vector,cov)
        result['replicates23']=replicas
        refs,tasks=direct_controls(cut,cfg,rows,nodes,rows22)
        checks=cached_stage(pool,workdir/'controles_angulares.jsonl',tasks,'controles angulares',workers);lookup={r['id']:r for r in checks}
        changes=[dict(**r,relative_change=lookup[r['id']]['P']/r['P']-1) for r in refs]
        result['angular_controls']=changes;result['angular_control_max_relative_change']=max(abs(r['relative_change']) for r in changes)
        check_ne=cfg['ne22']-2 if cfg['ne22']>=4 else cfg['ne22']+2
        control_nodes=_MODEL.quadrature22(cut,cfg['emax'],cfg['order22'],check_ne,cfg['nq22'])
        radial=cached_stage(pool,workdir/'control_radial22.jsonl',[(str(t[-1]),('22',t)) for t in control_nodes],'control radial 2→2',workers)
        I4=math.fsum(r['P'] for r in radial);D4=math.fsum(r['D'] for r in radial)
        T=result['I22']+result['I23'];D=result['D22']+result['D23']
        result['quadrature22_check']={'relative_I22_change':result['I22']/I4-1,
            'combined_mean_change':float(D/T-(D4+result['D23'])/(I4+result['I23'])),'check_ne22':check_ne}
        jvar=0.
        for band,rr in replicas.items():
            a=np.array([r['estimate_ID'] for r in rr]);n=len(a);center=a.mean(0)
            leave=np.array([(D+(center-v)[1]/(n-1))/(T+(center-v)[0]/(n-1)) for v in a])
            jvar+=(n-1)/n*np.sum((leave-leave.mean())**2)
        result['jackknife_mean_SE']=float(np.sqrt(jvar))
        result['complete']=True
        result['validation_passed']=bool(result['angular_control_max_relative_change']<.001 and abs(result['quadrature22_check']['relative_I22_change'])<.001)
        result['counts']={'23':len(rows),'22':len(rows22),'angular_controls':len(checks),'radial_check22':len(radial)}
        result['caveats']=['Errores estadísticos de la media; 22 fijo. No incluyen truncación de amplitudes ni todas las incertidumbres sistemáticas.',
            'Controles angulares puntuales y comparación radial; no constituyen una cota global de error.',
            'Mismos canales iterados y prescripción circular; sin delta externa de conservación de energía.']
        atomic_json(path,result);ok=True;return result
    finally:pool.shutdown(wait=ok)


def calculation_folder(out,cut,cfg,force=False):
    digest=hashlib.sha256(json.dumps(cfg,sort_keys=True).encode()).hexdigest()[:16]
    parent=out/'avance'/digest;parent.mkdir(parents=True,exist_ok=True)
    name='k_'+float(cut).hex().replace('+','p').replace('-','m')
    if not force:return parent/name
    previous=sorted(parent.glob(name+'_recalculo_*'))
    pending=[p for p in previous if not (p/'resultado.json').exists()]
    if pending:return pending[-1]
    return parent/(name+'_recalculo_'+str(len(previous)+1).zfill(4))


def main():
    ap=argparse.ArgumentParser(description='NSF: calcula nuevos puntos y los agrega al gráfico combinado con historial persistente.',formatter_class=argparse.ArgumentDefaultsHelpFormatter)
    ap.add_argument('--corte-ir','--ir','--cortes',dest='cuts',type=input_number,nargs='+',help='Uno o más valores de kappa_IR/Ei, por ejemplo 1e-8.')
    ap.add_argument('--emax','--energia-maxima',type=input_number,help='Emax/Ei; debe ser mayor que 16.')
    ap.add_argument('--salida',type=Path,default=Path(__file__).resolve().parent/'resultados_nsf',help='Carpeta del historial, las muestras y el gráfico.')
    ap.add_argument('--workers',type=int,default=min(4,max(1,(os.cpu_count() or 2)-1)))
    ap.add_argument('--solo-graficos','--solo-grafico',action='store_true',help='Redibuja todos los puntos archivados y locales, sin integrar.')
    ap.add_argument('--recalcular',action='store_true',help='Evalúa otra vez aunque el punto exista. El cálculo usa la semilla indicada.')
    ap.add_argument('--extraer-motor',action='store_true',help='Extrae el motor Python y sale.')
    group=ap.add_argument_group('Opciones de precisión; los valores por defecto usan la integración directa refinada')
    group.add_argument('--replicas',type=int,default=8);group.add_argument('--power-low',type=int,default=8);group.add_argument('--power-uv',type=int,default=7)
    group.add_argument('--orden23',type=int,default=16);group.add_argument('--orden22',type=int,default=16)
    group.add_argument('--ne22',type=int,default=6);group.add_argument('--nq22',type=int,default=6)
    group.add_argument('--seed',type=int,default=20261105,help='Semilla reproducible. Cambiala para obtener otras réplicas.')
    a=ap.parse_args()
    if a.workers<1 or a.replicas<2 or min(a.power_low,a.power_uv,a.orden23,a.orden22,a.ne22,a.nq22)<2:
        ap.error('workers>=1; réplicas, órdenes y potencias>=2.')
    if not a.solo_graficos and not a.extraer_motor:
        if a.cuts is None or a.emax is None:
            if not sys.stdin.isatty():ap.error('Indicá --corte-ir y --emax, o ejecutá sin argumentos desde una terminal para ingresarlos.')
            try:
                if a.cuts is None:a.cuts=[input_number(input('Corte IR / Ei (por ejemplo 1e-8): '))]
                if a.emax is None:a.emax=input_number(input('Energía máxima / Ei [2024]: ').strip() or '2024')
            except argparse.ArgumentTypeError as exc:ap.error(str(exc))
        if not a.emax>16:ap.error('Emax/Ei debe ser mayor que 16 para este motor de integración.')
        if any(not 0<k<.5 for k in a.cuts):ap.error('Cada corte IR/Ei debe estar entre 0 y 0.5.')
    out=a.salida.expanduser().resolve();out.mkdir(parents=True,exist_ok=True)
    if a.extraer_motor:
        root,digest=install_engine(out);print(f'Motor Python: {root}');return
    with history_lock(out):
        history=load_history(out)
        if a.solo_graficos:
            save_history(out,history);print(f'Gráfico con {len(active_points(history))} puntos: {out / "energia_media_combinada_EN.png"}');return
        root,digest=install_engine(out)
        cfg=dict(replicas=a.replicas,power_low=a.power_low,power_uv=a.power_uv,base_order=a.orden23,target_order=a.orden23,
                 order22=a.orden22,ne22=a.ne22,nq22=a.nq22,emax=a.emax,epsilon=1.,seed=a.seed,profile='directa_refinada',engine_sha256=digest,version=VERSION)
        for cut in sorted(set(a.cuts)):
            point={'kappa':cut,'Emax':a.emax}
            known=next((r for r in active_points(history) if point_equal(r,point)),None)
            if known is not None and not a.recalcular:
                result=known
                print(f'Ya existe kappa/Ei={cut:g}, Emax/Ei={a.emax:g}; se conserva. Usá --recalcular para evaluarlo otra vez.',flush=True)
            else:
                print(f'Calculando kappa/Ei={cut:g}, Emax/Ei={a.emax:g}. Puede tardar horas; Ctrl+C conserva el avance.',flush=True)
                workdir=calculation_folder(out,cut,cfg,a.recalcular)
                result=calculate_direct(cut,cfg,root,workdir,a.workers)
                append_result(history,result,cfg)
                if not result['validation_passed']:
                    save_history(out,history)
                    raise RuntimeError(f'El punto quedó guardado en {workdir}, pero no pasó los controles y no se agregó a la curva. Aumentá --orden23/--orden22 o --ne22 según el control que falla.')
            save_history(out,history)
            print(f'  <Eout>/Ei = {result["combined_mean"]:.12g} +/- {result["combined_mean_MC_SE"]:.3g}',flush=True)
        print(f'Historial: {out / "historial_nsf.json"}\nGráfico: {out / "energia_media_combinada_EN.png"}\nPDF: {out / "energia_media_combinada_EN.pdf"}',flush=True)



# Las constantes ENGINE_SOURCES y REFERENCE_RESULTS se añaden aquí como texto.
# Fuentes auditables: se pueden extraer mediante --extraer-motor.

ENGINE_SOURCES = {'precision23/engine.py': '"""Fixed-cut 23 calculation with algebraically stable spherical coordinates.\nNo angular cutoff and no changed finite-part prescription.\n"""\nfrom pathlib import Path\nimport sys,json,numpy as np\nROOT=Path(__file__).resolve().parent.parent\nsys.path.insert(0,str(ROOT));sys.path.insert(0,str(Path(__file__).parent))\nimport tmp_deep_ir23_engine as base\nimport motor_angulos\nimport polos_estable\noriginal_core=motor_angulos.core\nmotor_angulos.core=polos_estable\nbase.MAX=2024.\nKAPPA=.0005\n\ndef evaluate(u,order,index,seed,original=False,kappa=KAPPA):\n motor_angulos.core=original_core if original else polos_estable\n r=base.job((kappa,np.array(u),order,index,seed))\n if not all(np.isfinite(r[key]) for key in [\'P\',\'Q\',\'weight\']):raise FloatingPointError(\'Nonfinite amplitude retained as failure\')\n r[\'u5\']=np.array(u).tolist()\n return r\n', 'precision23/momenta.py': '"""Direct two-momentum importance sampling, Bose balance over six assignments.\nI23=(1/3!) integral d^3p d^3q W(p,q,-p-q), Etotal <= Emax.\nPDF is expressed relative to d^3p d^3q, including all 16*pi^2 orientation factors.\n"""\nimport json,time,argparse,numpy as np\nfrom concurrent.futures import ProcessPoolExecutor\nfrom scipy.stats import qmc\nfrom engine import ROOT,base,evaluate,KAPPA\nfrom amplitud_23 import generator,projected23,Kernel\nMAX=2024.;A=MAX/2;k=KAPPA\nL=np.log(A/k);T0=np.arctan((k-.5)/k);TZ=np.arctan((A-.5)/k)-T0\n\ndef pa(a):return .65/(k*TZ*(1+((a-.5)/k)**2))+.35/(a*L)\ndef pc(c):return .7/(c*L)+.2/(c*c*(1/k-1/A))+.1/(A-k)\ndef sample_a(v):\n if v<.65:return .5+k*np.tan(T0+TZ*v/.65)\n return k*np.exp(L*(v-.65)/.35)\ndef sample_c(v):\n if v<.7:return k*np.exp(L*v/.7)\n if v<.9:return 1/(1/k-(v-.7)/.2*(1/k-1/A))\n return k+(A-k)*(v-.9)/.1\n\ndef geometry(u):\n a=sample_a(u[0]);c=sample_c(u[1]);v=u[2]\n if v<.2:mu=10*v-1;st=np.sqrt(max(0,1-mu*mu))\n else:\n  z=(v-.2)/.8;sign=1 if z<.5 else -1;r=(2*z)%1;lam=(k/a)**2/2;t=lam*r/(1+lam-r);mu=sign*(1-t);st=np.sqrt(t*(2-t))\n nu=2*u[3]-1;su=np.sqrt(max(0,1-nu*nu));psi=2*np.pi*u[4]\n p=np.array([0.,0.,a]);q=c*np.array([su*np.cos(psi),su*np.sin(psi),nu])\n R=np.array([[mu,0,st],[0,1,0],[-st,0,mu]])\n ps=np.array([R@p,R@q,-R@(p+q)]);energies=np.linalg.norm(ps,axis=1);E=energies.sum()\n return ps,energies,E\n\ndef density(ps,ens):\n mus=ps[:,2]/ens;t=np.sum(ps[:,:2]**2,axis=1)/(ens*ens*(1+abs(mus)));lam=(k/ens)**2/2\n h=.2+.8*lam*(1+lam)/(t+lam)**2\n qa=pa(ens)*h/ens**2;qc=pc(ens)/ens**2\n return sum(qa[i]*qc[j] for i in range(3) for j in range(3) if i!=j)/(6*16*np.pi**2)\n\ndef run(task):\n u,n,i,seed=task;ps,ens,E=geometry(u);P=0.;W=0.;minimum=float(min(ens));f=0.\n if E<=MAX and min(ens)>=k:\n  v=np.r_[np.array([[0.,0.,.5],[0.,0.,-.5]]),ps];signed=np.r_[-v[:2],v[2:]]\n  norms=list(ens)\n  for a in range(5):\n   for b in range(a+1,5):\n    if (a,b)!=(0,1):norms.append(np.linalg.norm(signed[a]+signed[b]))\n  minimum=float(min(norms))\n  f=density(ps,ens)\n  if minimum>=k:\n   T,info=generator(v,Kernel(n));amp=projected23(T,info)[\'iteration\'];W=float(np.sum(abs(amp)**2)/4);P=W/(6*f)\n if not np.isfinite(P):raise FloatingPointError(\'Nonfinite kernel\')\n return {\'seed\':seed,\'index\':i,\'order\':n,\'u5\':u.tolist(),\'E\':float(E),\'energies\':ens.tolist(),\'momenta\':ps.tolist(),\'min_mode\':minimum,\'weight\':W,\'density\':f,\'P\':P,\'Q\':E*P}\nif __name__==\'__main__\':\n ap=argparse.ArgumentParser();ap.add_argument(\'--seeds\',type=int,nargs=\'+\',required=True);ap.add_argument(\'--power\',type=int,default=9);a=ap.parse_args();jobs=[]\n for s in a.seeds:jobs.extend((u,16,i,s) for i,u in enumerate(qmc.Sobol(5,scramble=True,seed=s).random_base2(a.power)))\n t=time.time();path=ROOT/f\'precision23/momenta_n16_p{a.power}_s{a.seeds[0]}.jsonl\'\n with path.open(\'w\') as f,ProcessPoolExecutor(6) as p:\n  for i,r in enumerate(p.map(run,jobs)):\n   f.write(json.dumps(r)+\'\\n\');f.flush()\n   if (i+1)%64==0:print(i+1,len(jobs),time.time()-t,flush=True)\n', 'precision23/uv_spectator.py': '"""UV importance mixture includes both genuinely soft and near-spectator legs.\nThe second selected leg has energy >=16/3; Bose balance preserves full support.\n"""\nimport json,time,argparse,numpy as np\nfrom concurrent.futures import ProcessPoolExecutor\nfrom scipy.stats import qmc\nfrom engine import ROOT\nimport momenta as m\nLO=16.;AMIN=LO/3;LUV=np.log(m.A/AMIN)\ndef pa(a):return .5/(m.k*m.TZ*(1+((a-.5)/m.k)**2))+.25/(a*a*(1/m.k-1/m.A))+.25/(a*m.L)\ndef sample_a(v):\n if v<.5:return .5+m.k*np.tan(m.T0+m.TZ*v/.5)\n if v<.75:return 1/(1/m.k-(v-.5)/.25*(1/m.k-1/m.A))\n return m.k*np.exp(m.L*(v-.75)/.25)\ndef pc(c):return np.where((c>=AMIN)&(c<=m.A),1/(c*LUV),0.)\ndef sample_c(v):return AMIN*np.exp(LUV*v)\ndef run(task):\n m.pa=pa;m.pc=pc;m.sample_a=sample_a;m.sample_c=sample_c\n r=m.run(task)\n if r[\'E\']<LO:r[\'P\']=0.;r[\'Q\']=0.\n return r\nif __name__==\'__main__\':\n ap=argparse.ArgumentParser();ap.add_argument(\'--seeds\',type=int,nargs=\'+\',default=[134111,148123,162109,176129]);a=ap.parse_args();jobs=[]\n for s in a.seeds:jobs.extend((u,16,i,s) for i,u in enumerate(qmc.Sobol(5,scramble=True,seed=s).random_base2(7)))\n t=time.time()\n with (ROOT/\'precision23/uv_spectator_n16_p7.jsonl\').open(\'w\') as f,ProcessPoolExecutor(6) as p:\n  for i,r in enumerate(p.map(run,jobs)):\n   f.write(json.dumps(r)+\'\\n\');f.flush()\n   if (i+1)%32==0:print(i+1,len(jobs),time.time()-t,flush=True)\n', 'precision23/polos_estable.py': '"""Circular finite-part diagnostic of the unfiltered five-block kernel.\n\nSmooth disjoint partitions around both daughter poles and the extraction pole.\nEvery cap is integrated down to zero radius: no cone is discarded. Azimuthal\naverages precede radial integration there. This implements a declared circular\nextension of the off-diagonal closed Greens, not a proof that heat regularization\nor the full NSF distributional prescription selects this extension.\n"""\nfrom functools import lru_cache\nimport numpy as np\nfrom stable_geometry import canonical\nfrom scipy.special import roots_legendre\nfrom nucleo_uv import frame, HELS, exchange_parts, configuration, enc\n\nDIAGNOSTICS=[]\n# Reflection of the canonical planar geometry permits exact half-sphere integration.\n\n@lru_cache(None)\ndef gauss(n):return roots_legendre(n)\n\ndef bump(y):\n    a=np.clip((y-.25)/.75,0,1)\n    return 1-a*a*a*(10+a*(-15+6*a))\n\ndef green(n,m,nj,mj):\n    X=np.sum((n-nj)**2,axis=-1)/4\n    a=-(m@nj)/np.sqrt(2);b=-(n@mj)/np.sqrt(2);c=-(m@mj)\n    return (a*b-X*c)**2/(2*np.pi*X**3)\n\ndef dyad(n):\n    phi=np.arctan2(n[...,1],n[...,0]);st=np.hypot(n[...,0],n[...,1]);z=n[...,2]\n    return np.stack((z*np.cos(phi)-1j*np.sin(phi),z*np.sin(phi)+1j*np.cos(phi),-st),axis=-1)/np.sqrt(2)\n\ndef segment_grid(edges,order):\n    edges=sorted(set(float(e) for e in edges));q,w=gauss(order)\n    pts=[];weights=[]\n    for lo,hi in zip(edges[:-1],edges[1:]):\n        if not hi>lo:continue\n        pts.append((lo+hi)/2+(hi-lo)/2*q);weights.append((hi-lo)/2*w)\n    return np.concatenate(pts),np.concatenate(weights)\n\ndef aligned_blocks(pv,qv,order=16,cap_fraction=.35,shift=.173):\n    pv=np.asarray(pv,float);qv=np.asarray(qv,float)\n    p=np.linalg.norm(pv);q=np.linalg.norm(qv);s=np.linalg.norm(pv+qv)\n    s,u,v,rotation=canonical(pv,qv)\n    nu,mu=frame(u);nv,mv=frame(v);ns,ms=frame(np.array([0.,0.,s]))\n    dot=p*q*np.sum((pv/p-qv/q)**2)/2;defect=2*dot/(p+q+s)\n    if defect<=0:raise ValueError(\'Positive defect required\')\n    centers=[nu,nv,ns]\n    if not 0<cap_fraction<.5:raise ValueError(\'Disjoint caps require 0<fraction<1/2\')\n    # atan2 of cross/dot is stable for the small UV angular separations.\n    radii=[cap_fraction*min(np.arctan2(np.linalg.norm(np.cross(a,b)),a@b)\n                           for j,b in enumerate(centers) if j!=i)\n           for i,a in enumerate(centers)]\n    caps=[2*np.sin(r/2)**2 for r in radii]\n\n    def integrand(n):\n        m=dyad(n);z=n[...,2]\n        trans=n[...,0]**2+n[...,1]**2\n        oneplus=np.divide(trans,1-z,out=(1+z).copy(),where=z<0)\n        t=np.divide(trans,1+z,out=(1-z).copy(),where=z>=0)\n        D=(defect+s*t)/np.sqrt(2)\n        C=p*q*np.sum((n-nu)**2,axis=-1)*np.sum((n-nv)**2,axis=-1)/8\n        A=(C/D)**2\n        R=oneplus/(8*np.pi);Rp=1/(8*np.pi)\n        fr=R/D;fp=Rp/D+R*s/np.sqrt(2)/D**2\n        fpp=np.sqrt(2)*s*Rp/D**2+s*s*R/D**3\n        lap=trans*fpp-2*z*fp-4*fr/trans\n        h=green(n,m,nu,mu)*green(n,m,nv,mv).conj()\n        phase=(n[...,0]+1j*n[...,1])**2/trans\n        out=np.empty(n.shape[:-1]+(2,2,3),complex)\n        for ih,ph in enumerate((phase,phase.conj())):\n          for j,hh in enumerate((h,h.conj())):\n            out[...,ih,j,0]=2*lap*ph*C*hh\n            out[...,ih,j,1]=2*lap*ph*A*hh\n            out[...,ih,j,2]=dot*fr*ph*hh\n        return out\n\n    import os\n    if os.environ.get(\'FUSED_INTEGRAND\')==\'1\':\n        from fused_integrand import factory\n        integrand=factory(nu,nv,mu,mv,p,q,s,defect,dot)\n\n    # Body quadrature resolves cap transitions plus the parent energy cone.\n    tedges=[0.,2.]\n    scale=max(defect/s,1e-14)\n    while scale<2:tedges.append(scale);scale*=2\n    phiedges=[0.,np.pi,2*np.pi]\n    for center,r in zip(centers,radii):\n        theta=np.arctan2(np.hypot(center[0],center[1]),center[2])\n        for a in [.5,1.,2.]:\n            tedges.extend([2*np.sin(max(0,theta-a*r)/2)**2,2*np.sin(min(np.pi,theta+a*r)/2)**2])\n        tedges.append(np.sum((center-ns)**2)/2)\n        if np.sin(theta)>1e-14:\n            width=min(r/np.sin(theta),np.pi/2)\n            while width<np.pi/2:\n                for origin in [0.,np.pi,2*np.pi]:\n                    phiedges.extend([a for a in [origin-width,origin+width] if 0<a<2*np.pi])\n                width*=2\n    # Unit-vector roundoff can place an exact south-pole edge a few ulps above 2.\n    # Project integration bounds back onto the sphere; no physical cap is removed.\n    tedges=[float(np.clip(a,0.,2.)) for a in tedges]\n    if os.environ.get(\'FINE_POLAR_GRID\')==\'1\':\n        # Resolve the shoulder between tiny daughter caps and the wider energy cone.\n        # Previously a single Gauss interval could span five or more decades.\n        fine_scale=min([defect/s]+caps)/4\n        if fine_scale<=0:raise FloatingPointError(\'Positive angular scale required\')\n        while fine_scale<2:\n            tedges.extend([fine_scale,2-fine_scale]);fine_scale*=2\n        tedges=[float(np.clip(a,0.,2.)) for a in tedges]\n    tg,wx=segment_grid(tedges,order);phi,wp=segment_grid([a for a in phiedges if a<=np.pi],order)\n    # Recover the distance from the south pole before rounding t close to 2.\n    southedges=sorted(set(float(x) for x in tedges));gx,_=gauss(order)\n    south=np.concatenate([(2-hi)+(hi-lo)*(1-gx)/2 for lo,hi in zip(southedges[:-1],southedges[1:]) if hi>lo])\n    assert len(south)==len(tg)\n    body=np.zeros((2,2,3),complex);body_area=0.\n    for k in range(0,len(tg),16):\n        t=tg[k:k+16,None];z=1-t;ds=south[k:k+16,None]\n        st=np.sqrt(np.where(t<=1,t*(2-t),ds*(2-ds)))\n        n=np.stack(np.broadcast_arrays(st*np.cos(phi),st*np.sin(phi),z),axis=-1)\n        chi=np.zeros(n.shape[:-1])\n        for c,tmax in zip(centers,caps):chi+=bump(np.sum((n-c)**2,axis=-1)/(2*tmax))\n        complement=np.maximum(0,1-chi)\n        body_area+=float(2*np.sum(wx[k:k+16,None]*wp[None,:]*complement))\n        body+=np.einsum(\'ab,abijk->ijk\',wx[k:k+16,None]*wp[None,:]*complement,2*integrand(n).real)\n    polar,wpolar=gauss(order)\n    nphi=4*order+8;phi=np.pi*(np.arange(nphi)+.5)/nphi\n    cap_values=[]\n    for c,tmax in zip(centers,caps):\n        t=tmax*(1+polar[:,None])/2\n        e1=np.array([c[2],0.,-c[0]]);e2=np.array([0.,1.,0.])\n        n=(1-t)[...,None]*c+np.sqrt(t*(2-t))[...,None]*(np.cos(phi)[...,None]*e1+np.sin(phi)[...,None]*e2)\n        # Angular mean first implements circular cancellation of leading poles.\n        avg=integrand(n).real.mean(axis=1)*2*np.pi\n        val=np.einsum(\'a,aijk->ijk\',wpolar*tmax/2*bump(t[:,0]/tmax),avg)\n        cap_values.append(val)\n    nonlocal_sum=body+sum(cap_values)\n    cap_area=sum(2*np.pi*np.sum(wpolar*tmax/2*bump((1+polar)/2)) for tmax in caps)\n    DIAGNOSTICS.append({\'order\':order,\'cap_fraction\':cap_fraction,\'radii\':radii,\n                        \'sphere_area_error\':float((body_area+cap_area)/(4*np.pi)-1)})\n    out=np.zeros((2,4,5),complex)\n    common=-1j*defect/(2*np.pi*np.sqrt(2)*s)\n    out[:,:2,:3]=.5*common*nonlocal_sum\n    pair=green(nu,mu,nv,mv)\n    for ih,mh in enumerate((ms,ms.conj())):\n        def f_at(c):\n            tr=c[0]**2+c[1]**2\n            op=tr/(1-c[2]) if c[2]<0 else 1+c[2]\n            tt=1-c[2] if c[2]<0 else tr/(1+c[2])\n            return op/(8*np.pi)/((defect+s*tt)/np.sqrt(2))*2*(c@mh)**2/tr\n        out[ih,2,3]=.5*common*dot*f_at(nu)*pair.conjugate()\n        out[ih,2,4]=.5*common*dot*f_at(nv)*pair.conjugate()\n        out[ih,3,3]=.5*common*dot*f_at(nu)*pair\n        out[ih,3,4]=.5*common*dot*f_at(nv)*pair\n    phases=[]\n    for old,new in zip((pv+qv,pv,qv),(np.array([0.,0.,s]),u,v)):\n        old_m=rotation@frame(old)[1];new_m=frame(new)[1]\n        z=new_m@old_m.conj();phases.append(z/abs(z))\n    basis=np.array([[phases[0]**ho*phases[1]**(-hu)*phases[2]**(-hv) for hu,hv in HELS] for ho in (2,-2)])\n    return out/basis[:,:,None]\n\nclass Kernel:\n    def __init__(self,order=16,cap_fraction=.35,shift=.173):\n        self.order=order;self.cap_fraction=cap_fraction;self.shift=shift;self.cache={}\n    def __call__(self,u,v):\n        u=np.asarray(u,float);v=np.asarray(v,float);a=tuple(u);b=tuple(v);swap=a>b\n        key=(b,a) if swap else (a,b)\n        if key not in self.cache:\n            uu,vv=(v,u) if swap else (u,v)\n            src=aligned_blocks(uu,vv,self.order,self.cap_fraction,self.shift)\n            factor=2/np.sqrt(np.pi)*(np.linalg.norm(uu+vv)/(np.linalg.norm(uu)*np.linalg.norm(vv)))**1.5\n            tensor=np.zeros((2,2,2),complex)\n            for ih in range(2):\n                for j,(hu,hv) in enumerate(HELS):tensor[ih,int(hu<0),int(hv<0)]=factor*src[ih,j].sum()\n            self.cache[key]=tensor\n        out=self.cache[key]\n        return out.swapaxes(1,2) if swap else out\n\ndef evaluate(E,mu=.8,order=16,cap_fraction=.35,shift=.173):\n    parts=exchange_parts(configuration(E/2,np.arccos(mu)),Kernel(order,cap_fraction,shift))\n    m=parts[\'iteration\'];gas=m/(.25*E)\n    return {\'E\':E,\'mu\':mu,\'order\':order,\'cap_fraction\':cap_fraction,\'shift\':shift,\n            \'weight\':float(np.sum(abs(gas)**2)/4),\'matrix\':enc(m)}\n', 'tmp_deep_ir23_engine.py': '"""Exploratory fully integrated 2->3 means with explicit finite UV bounds."""\nimport numpy as np,json,time,argparse\nfrom scipy.stats import qmc\nfrom concurrent.futures import ProcessPoolExecutor\nimport tmp_ir002_mis as m\nCUTS=[.005,.01,.02,.05,.1,.2]\nMAX=2024.\ndef qa(a,E):\n k=m.KAPPA;A=min(E/2,E-2*k);L=np.log(A/k);delta=k*k/E;Ld=np.log1p((A-k)/delta)\n Z=np.arctan((A-.5)/k)-np.arctan((k-.5)/k)\n return (1/(a*L)+1/(k*Z*(1+((a-.5)/k)**2))+1/((A-a+delta)*Ld))/3\n\ndef geometry(u,E):\n k=m.KAPPA;A=E/2;U=min(A,E-2*k);component=min(2,int(u[0]*3));r=u[0]*3-component\n L=np.log(U/k);delta=k*k/E;Ld=np.log1p((U-k)/delta)\n if component==0:a=k*np.exp(L*r)\n elif component==1:\n  t0=np.arctan((k-.5)/k);Z=np.arctan((U-.5)/k)-t0;a=.5+k*np.tan(t0+Z*r)\n else:a=U-delta*np.expm1(Ld*r)\n dA=(A-U)+delta*np.expm1(Ld*r) if component==2 else A-a\n lo=max(k,A-a);hi=min(A,E-a-k);D=hi-lo;Lb=np.log1p(D/k)\n component_b=min(3,int(u[1]*4));rb=4*u[1]-component_b\n if component_b<2:b=lo+D*((component_b+rb)/2)\n elif component_b==2:b=lo+k*np.expm1(Lb*rb)\n else:b=hi-k*np.expm1(Lb*rb)\n c=E-a-b\n if u[2]<.5:\n  mu=4*u[2]-1;st=np.sqrt(max(0,1-mu*mu))\n else:\n  z=2*u[2]-1;sign=1 if z<.5 else -1;r2=(2*z)%1\n  lam=(k/a)**2/2;t=lam*r2/(1+lam-r2);mu=sign*(1-t);st=np.sqrt(t*(2-t))\n psi=2*np.pi*u[3]\n tp=dA*(E-2*b)/(a*b);tm=E*(E-2*c)/(2*a*b)\n cb=np.clip((tp-tm)/2,-1,1);sb=np.sqrt(max(0,tp*tm));norm=np.hypot(cb,sb);cb/=norm;sb/=norm\n p=np.array([0,0,a]);q=np.array([b*sb,0,b*cb]);cp,sp=np.cos(psi),np.sin(psi)\n R=np.array([[mu,0,st],[0,1,0],[-st,0,mu]])@np.array([[cp,-sp,0],[sp,cp,0],[0,0,1]])\n ps=np.array([R@p,R@q,-R@(p+q)]);ens=np.array([a,b,c]);mus=ps[:,2]/ens\n lengths=np.minimum(A,E-ens-k)-np.maximum(k,A-ens)\n lam=(k/ens)**2/2;t=np.sum(ps[:,:2]**2,axis=1)/(ens**2*(1+np.abs(mus)));ho=.5+.5*lam*(1+lam)/(t+lam)**2\n los=np.maximum(k,A-ens);his=np.minimum(A,E-ens-k);bvals=np.roll(ens,-1)\n Lbs=np.log1p(lengths/k)\n pb=.5/lengths+.25/(Lbs*(bvals-los+k))+.25/(Lbs*(his-bvals+k))\n density=np.mean(qa(ens,E)*pb*ho)\n return ps,ens,mus,8*np.pi**2/6*a*b*c/density\nm.geometry=geometry\n\ndef job(args):\n k,u,n,i,seed=args;m.KAPPA=k\n lo=3*k;L=np.log(MAX/lo);t0=np.arctan((lo-1)/k);Z=np.arctan((MAX-1)/k)-t0\n if u[4]<.5:E=lo*np.exp(L*2*u[4])\n else:E=1+k*np.tan(t0+Z*(2*u[4]-1))\n density=.5/(E*L)+.5/(k*Z*(1+((E-1)/k)**2))\n r=m.run((u[:4],E,n,i,seed));r[\'k\']=k;r[\'P\']=r[\'value\']/density;r[\'Q\']=E*r[\'P\']\n return r\nif __name__==\'__main__\':\n ap=argparse.ArgumentParser();ap.add_argument(\'--power\',type=int,default=7);ap.add_argument(\'--order\',type=int,default=8);ap.add_argument(\'--seed\',type=int,default=3451);args=ap.parse_args()\n us=qmc.Sobol(5,scramble=True,seed=args.seed).random_base2(args.power)\n jobs=[(k,u,args.order,i,args.seed) for k in CUTS for i,u in enumerate(us)]\n name=f\'tmp_media23_endpoint_n{args.order}_p{args.power}_s{args.seed}.jsonl\';start=time.time()\n with open(name,\'w\') as f,ProcessPoolExecutor(6) as pool:\n  for j,r in enumerate(pool.map(job,jobs,chunksize=1)):\n   f.write(json.dumps(r)+\'\\n\');f.flush()\n   if (j+1)%64==0:print(j+1,len(jobs),round(time.time()-start,1),flush=True)\n', 'tmp_ir002_mis.py': '"""Corrected 3-body phase measure and Bose-symmetrized importance sampling.\nrho=(8*pi^2/3!)*integral a*b*c W da db dHaar.\nProposal chooses an outgoing leg uniformly (permutation cancels for the\nsymmetrized observable), then its energy and its beam angle. Balance density\nis the mean of the three leg densities, all relative to da db dHaar.\n"""\nimport sys,json,time,argparse\nfrom pathlib import Path\nfrom concurrent.futures import ProcessPoolExecutor\nimport numpy as np\nfrom scipy.stats import qmc\nfrom scipy.integrate import quad\nROOT=Path(__file__).parent\nsys.path.insert(0,str(ROOT/\'canal_23\'))\nfrom amplitud_23 import generator,projected23,Kernel\nKAPPA=.02\n\ndef qa(a,E):\n A=E/2;k=KAPPA;L=np.log(A/k);delta=k*k/E;D=A-k;Ld=np.log1p(D/delta)\n Z=np.arctan((A-.5)/k)-np.arctan((k-.5)/k)\n return (1/(a*L)+1/(k*Z*(1+((a-.5)/k)**2))+1/((A-a+delta)*Ld))/3\n\ndef geometry(u,E):\n k=KAPPA;A=E/2;component=min(2,int(u[0]*3));r=u[0]*3-component\n L=np.log(A/k);delta=k*k/E;Ld=np.log1p((A-k)/delta)\n if component==0:a=k*np.exp(L*r)\n elif component==1:\n  t0=np.arctan((k-.5)/k);Z=np.arctan((A-.5)/k)-t0;a=.5+k*np.tan(t0+Z*r)\n else:a=A-delta*np.expm1(Ld*r)\n lo=max(k,A-a);hi=min(A,E-a-k);b=lo+(hi-lo)*u[1];c=E-a-b\n if u[2]<.5:mu=4*u[2]-1\n else:\n  z=2*u[2]-1;sign=1 if z<.5 else -1;r2=(2*z)%1\n  lam=(k/a)**2/2;t=lam*r2/(1+lam-r2);mu=sign*(1-t)\n psi=2*np.pi*u[3];st=np.sqrt(max(0,1-mu*mu))\n cosbeta=np.clip((c*c-a*a-b*b)/(2*a*b),-1,1);sinbeta=np.sqrt(max(0,1-cosbeta*cosbeta))\n p=np.array([0,0,a]);q=np.array([b*sinbeta,0,b*cosbeta])\n cp,sp=np.cos(psi),np.sin(psi)\n R=np.array([[mu,0,st],[0,1,0],[-st,0,mu]])@np.array([[cp,-sp,0],[sp,cp,0],[0,0,1]])\n ps=np.array([R@p,R@q,-R@(p+q)]);energies=np.array([a,b,c]);mus=ps[:,2]/energies\n lengths=np.minimum(A,E-energies-k)-np.maximum(k,A-energies)\n lam=(k/energies)**2/2;t=1-np.abs(mus)\n horient=.5+.5*lam*(1+lam)/(t+lam)**2\n density=np.mean(qa(energies,E)/lengths*horient)\n volume=8*np.pi**2/6*a*b*c/density\n return ps,energies,mus,volume\n\ndef run(job):\n u,E,n,i,seed=job;ps,energies,mus,volume=geometry(u,E)\n v=np.r_[np.array([[0,0,.5],[0,0,-.5]]),ps]\n signed=np.r_[-v[:2],v[2:]]\n norms=[*energies]\n for a in range(5):\n  for b in range(a+1,5):\n   if (a,b)!=(0,1):norms.append(np.linalg.norm(signed[a]+signed[b]))\n minimum=min(norms)\n W=0.\n if minimum>=KAPPA:\n  T,info=generator(v,Kernel(n));amp=projected23(T,info)[\'iteration\'];W=float(np.sum(abs(amp)**2)/4)\n return {\'E\':E,\'order\':n,\'index\':i,\'seed\':seed,\'mus\':mus.tolist(),\'energies\':energies.tolist(),\n         \'min_mode\':float(minimum),\'weight\':W,\'value\':float(volume*W),\'phase_volume\':float(volume),\'u\':u.tolist()}\n\ndef control():\n for E in [.5,1.,128.]:\n  us=qmc.Sobol(4,scramble=True,seed=811).random_base2(14)\n  values=[geometry(u,E)[-1] for u in us]\n  k=KAPPA;A=E/2\n  exact=8*np.pi**2/6*quad(lambda a:quad(lambda b:a*b*(E-a-b),max(k,A-a),min(A,E-a-k),epsabs=1e-12)[0],k,A,epsabs=1e-10)[0]\n  print(\'volume\',E,np.mean(values),exact,\'rel\',np.mean(values)/exact-1,flush=True)\n\nif __name__==\'__main__\':\n ap=argparse.ArgumentParser();ap.add_argument(\'--power\',type=int,default=7);ap.add_argument(\'--order\',type=int,default=8);ap.add_argument(\'--seed\',type=int,default=811);ap.add_argument(\'--control\',action=\'store_true\');a=ap.parse_args()\n if a.control:control();sys.exit()\n us=qmc.Sobol(4,scramble=True,seed=a.seed).random_base2(a.power)\n jobs=[(u,E,a.order,i,a.seed) for E in [.5,.8,1.,128.,512.,2048.] for i,u in enumerate(us)]\n path=ROOT/f\'tmp_ir002_n{a.order}_p{a.power}_s{a.seed}.jsonl\';start=time.time()\n with path.open(\'w\') as f,ProcessPoolExecutor(6) as pool:\n  for j,r in enumerate(pool.map(run,jobs)):\n   f.write(json.dumps(r)+\'\\n\');f.flush()\n   if (j+1)%64==0:print(j+1,len(jobs),round(time.time()-start,1),flush=True)\n', 'canal_23/amplitud_23.py': '"""Leading connected 2->3: physical T1^3, with explicit missing T2/T3 inputs.\n\nCanonical oscillator normalization and common momentum-cell v. Momentum pool\ncontains all signed two-leaf sums: every internal edge of a cubic five-leg tree\nhas such a routing. For generic distinct external momenta, disconnected T1^3\nterms require a 1->1 spectator/self-energy with equal initial/final momentum,\nwhich is excluded by the external-data check. No occupation truncation.\n"""\nfrom pathlib import Path\nfrom itertools import combinations,product\nfrom collections import defaultdict\nimport sys,math,time\nimport numpy as np\nROOT=Path(__file__).resolve().parent\nsys.path.insert(0,str(ROOT/\'cola_uv_BR0\'))\nfrom motor_angulos import Kernel,enc\n\ndef key(v):return tuple(np.round(v,12))\n\ndef apply_term(state,cre,ann):\n    """Unit-normalized canonical occupations, arbitrary reachable particle count."""\n    ns=list(state);factor=1.\n    for a in ann:\n        count=ns.count(a)\n        if not count:return None,0.\n        factor*=math.sqrt(count);ns.remove(a)\n    for c in cre:factor*=math.sqrt(ns.count(c)+1);ns.append(c)\n    return tuple(sorted(ns)),factor\n\ndef apply(terms,vector,targets=None):\n    out=defaultdict(complex)\n    for state,amplitude in vector.items():\n      for (cre,ann),coefficient in terms.items():\n        st,factor=apply_term(state,cre,ann)\n        if factor and (targets is None or st in targets):out[st]+=coefficient*factor*amplitude\n    return {k:z for k,z in out.items() if z!=0}\n\ndef add_term(terms,cre,ann,z):\n    cre=tuple(sorted(cre));ann=tuple(sorted(ann))\n    terms[(cre,ann)]+=z\n\ndef hermitian_pair(terms,cre,ann,z):\n    add_term(terms,cre,ann,z);add_term(terms,ann,cre,z.conjugate())\n\ndef inner(a,b):return sum(z.conjugate()*b.get(s,0j) for s,z in a.items())\n\ndef momentum_pool(vectors):\n    v=np.asarray(vectors,float);nin=2\n    if v.shape not in [(4,3),(5,3)]:raise ValueError(\'Two inputs, two or three outputs required\')\n    if not np.allclose(v[:nin].sum(0),v[nin:].sum(0),rtol=0,atol=1e-11):raise ValueError(\'Spatial momentum must be conserved\')\n    if any(key(a)==key(b) for a in v[:nin] for b in v[nin:]):\n        raise ValueError(\'Generic no-spectator support required by this direct projection engine\')\n    if len({key(a) for a in v})!=len(v):raise ValueError(\'External modes must be distinct\')\n    momenta=[];lookup={};excluded=[]\n    def register(p):\n        k=key(p)\n        if np.linalg.norm(p)==0:\n            excluded.append(k);return None\n        if k==(0.,0.,0.):raise ValueError(\'Nonzero momentum below routing precision; refine the momentum keys\')\n        if k not in lookup:lookup[k]=len(momenta);momenta.append(np.asarray(p,float))\n        return lookup[k]\n    external=[register(p) for p in v]\n    signed=np.concatenate((-v[:2],v[2:]))\n    for a,b in combinations(signed,2):\n        register(a+b);register(-a-b)\n    return momenta,lookup,external,excluded\n\ndef momentum_pool_cm_exact(vectors):\n    """Integer leaf labels identify the exact CM momentum relations.\n\n    Floating vectors keep their original values for the angular kernel. Decimal\n    rounding never decides whether a parent routing or an internal mode exists.\n    """\n    v=np.asarray(vectors,float)\n    if v.shape not in [(4,3),(5,3)] or not np.array_equal(v[0],-v[1]):\n        raise ValueError(\'This exact leaf basis requires two opposite input momenta\')\n    if not np.allclose(v[:2].sum(0),v[2:].sum(0),rtol=0,atol=1e-11):\n        raise ValueError(\'Spatial momentum must be conserved\')\n    if any(key(a)==key(b) for a in v[:2] for b in v[2:]):\n        raise ValueError(\'Generic no-spectator support required\')\n    if len({key(a) for a in v})!=len(v):raise ValueError(\'External modes must be distinct\')\n    coeff=np.array([[1,0,0],[-1,0,0],[0,1,0],[0,0,1],[0,-1,-1]],int) if len(v)==5 else np.array([[1,0],[-1,0],[0,1],[0,-1]],int)\n    momenta=[];labels=[];lookup={};excluded=[]\n    def register(p,c):\n        label=tuple(map(int,c))\n        if not any(label):excluded.append(label);return None\n        if not np.linalg.norm(p):raise ValueError(\'Nonzero symbolic routing has zero numerical momentum\')\n        if label not in lookup:\n            lookup[label]=len(momenta);momenta.append(np.asarray(p,float));labels.append(c.copy())\n        return lookup[label]\n    external=[register(p,c) for p,c in zip(v,coeff)]\n    signed=np.concatenate((-v[:2],v[2:]));sc=np.concatenate((-coeff[:2],coeff[2:]))\n    for a,b in combinations(range(len(v)),2):\n        register(signed[a]+signed[b],sc[a]+sc[b]);register(-signed[a]-signed[b],-sc[a]-sc[b])\n    return momenta,lookup,external,excluded,labels\n\ndef generator(vectors,kernel,cell=1.):\n    """One unordered spatial daughter pair; same-mode helicities remain ordered.\n\nOrdered-slot gamma=-i sqrt(v) K/(4 sqrt(wp wu wv)); distinct spatial daughters\nhave two equivalent slots, giving denominator 2. This is calibrated to 2->2.\n"""\n    v=np.asarray(vectors,float)\n    exact_cm=v.shape in [(4,3),(5,3)] and np.array_equal(v[0],-v[1])\n    if exact_cm:momenta,lookup,external,excluded,labels=momentum_pool_cm_exact(v)\n    else:momenta,lookup,external,excluded=momentum_pool(v)\n    w=np.array([np.linalg.norm(p) for p in momenta]);terms=defaultdict(complex);triads=[]\n    for u in range(len(momenta)):\n      for vv in range(u,len(momenta)):\n        parent=lookup.get(tuple(labels[u]+labels[vv])) if exact_cm else lookup.get(key(momenta[u]+momenta[vv]))\n        if parent is None:continue\n        if not np.any(np.cross(np.asarray(momenta[u],np.longdouble),np.asarray(momenta[vv],np.longdouble))):\n            raise ValueError(\'Collinear vertex found; its unfiltered distribution is not assigned a point value\')\n        tensor=kernel(momenta[u],momenta[vv]);triads.append((parent,u,vv))\n        denom=4 if u==vv else 2\n        for hp,hu,hv in product((0,1),repeat=3):\n            z=-1j*math.sqrt(cell)*tensor[hp,hu,hv]/(denom*math.sqrt(w[parent]*w[u]*w[vv]))\n            hermitian_pair(terms,(2*parent+hp,),(2*u+hu,2*vv+hv),complex(z))\n    return dict(terms),{\'momenta\':momenta,\'frequencies\':w,\'external\':external,\'triads\':triads,\n                        \'excluded_zero_routings\':len(excluded),\'canonical_vertices\':len(kernel.cache),\n                        \'routing\':\'exact_integer_leaf_labels_in_CM\' if exact_cm else \'legacy_non_CM\'}\n\ndef states(info,nout):\n    ext=info[\'external\']\n    ins=[tuple(sorted(2*ext[j]+h[j] for j in range(2))) for h in product((0,1),repeat=2)]\n    outs=[tuple(sorted(2*ext[j+2]+h[j] for j in range(nout))) for h in product((0,1),repeat=nout)]\n    return ins,outs\n\ndef projected23(T1,info,T2=None,T3=None):\n    """Returns cubic iteration and supplied mixed/contact matrices in box units.\n\nFor the actual physical calculation unavailable T2/T3 are None and stay None.\nExplicit empty dictionaries are accepted ONLY for algebraic null controls.\n"""\n    ins,outs=states(info,3)\n    first_i=[apply(T1,{s:1.}) for s in ins];first_f=[apply(T1,{s:1.}) for s in outs]\n    targets=set().union(*(v.keys() for v in first_f))\n    second_i=[apply(T1,v,targets) for v in first_i]\n    A=np.array([[-1j/6*inner(f,v) for v in second_i] for f in first_f])\n    B12=B21=C=None\n    if T2 is not None:\n        ti2=[apply(T2,{s:1.}) for s in ins]\n        tf2=[apply(T2,{s:1.}) for s in outs]\n        B12=np.array([[-.5*inner(f,v) for v in ti2] for f in first_f])\n        B21=np.array([[-.5*inner(f,v) for v in first_i] for f in tf2])\n    if T3 is not None:\n        C=np.array([[1j*apply(T3,{i:1.},set(outs)).get(f,0j) for i in ins] for f in outs])\n    return {\'iteration\':A,\'mixed_T1_T2\':B12,\'mixed_T2_T1\':B21,\'contact\':C,\n            \'initial_one_step_states\':[len(v) for v in first_i],\n            \'final_one_step_states\':[len(v) for v in first_f],\n            \'middle_states\':[len(v) for v in second_i]}\n\ndef assemble(A,B12,B21,C,source_record):\n    if any(x is None for x in (A,B12,B21,C)):\n        raise ValueError(\'Incomplete 2->3: independent mixed sectors and quintic contact must be supplied\')\n    if not source_record:raise ValueError(\'State sources, conventions and prescriptions for every block\')\n    A,B12,B21,C=(np.asarray(x,complex) for x in (A,B12,B21,C))\n    if any(x.shape!=(8,4) for x in (A,B12,B21,C)):raise ValueError(\'Each matrix must be 8 final x 4 initial helicities\')\n    B=B12+B21;M=A+B+C\n    avg=lambda x:float(np.sum(x)/4)\n    blocks={\'AA\':avg(abs(A)**2),\'BB\':avg(abs(B)**2),\'CC\':avg(abs(C)**2),\n            \'AB\':avg(2*np.real(A*B.conj())),\'AC\':avg(2*np.real(A*C.conj())),\n            \'BC\':avg(2*np.real(B*C.conj()))}\n    return {\'matrix\':M,\'weight\':avg(abs(M)**2),\'six_blocks\':blocks,\n            \'six_block_residual\':abs(sum(blocks.values())-avg(abs(M)**2)),\n            \'source_record\':source_record}\n\ndef configuration(scale=1.):\n    out=np.array([[.3,.1,.2],[-.2,.25,-.15],[-.1,-.35,-.05]])*scale\n    return np.concatenate((np.array([[0,0,.5],[0,0,-.5]]),out))\n\ndef evaluate_iteration(scale=1.,order=24,cell=1.,cap_fraction=.35):\n    start=time.time();v=configuration(scale);kernel=Kernel(order,cap_fraction)\n    T,info=generator(v,kernel,cell);p=projected23(T,info)\n    Ag=p[\'iteration\']/cell**1.5;freq=np.linalg.norm(v,axis=1)\n    m=Ag*math.sqrt(np.prod(freq))\n    return {\'status\':\'T1_CUBED_ITERATION_ONLY_NOT_COMPLETE_23\',\n            \'Ei\':1.,\'Ef\':float(sum(freq[2:])),\'scale\':scale,\'order\':order,\'cell\':cell,\n            \'cap_fraction\':cap_fraction,\'external_vectors\':v.tolist(),\n            \'helicity_order\':\'Rows h3,h4,h5; columns h1,h2; each axis ordered (+2,-2)\',\n            \'matrix_AG_iteration\':enc(Ag),\'matrix_reduced_m_iteration\':enc(m),\n            \'iteration_only_reduced_weight\':float(np.sum(abs(Ag)**2)/4),\n            \'momentum_modes\':len(info[\'momenta\']),\'triads\':len(info[\'triads\']),\n            \'momentum_pool\':np.asarray(info[\'momenta\']).tolist(),\n            \'pool_frequencies\':info[\'frequencies\'].tolist(),\'triad_indices\':info[\'triads\'],\n            \'canonical_vertices\':info[\'canonical_vertices\'],\'operator_terms\':len(T),\n            \'excluded_zero_routings\':info[\'excluded_zero_routings\'],\n            \'initial_one_step_states\':p[\'initial_one_step_states\'],\n            \'final_one_step_states\':p[\'final_one_step_states\'],\n            \'middle_states\':p[\'middle_states\'],\n            \'missing\':[\'T2 quartic (3 creators,1 annihilator) / C_R\',\'T3 quintic (3 creators,2 annihilators)\'],\n            \'normalization\':\'M_box_iteration=epsilon^3 v^(3/2) AG_iteration; sum of final states uses 1/3!; squared order epsilon^6\',\n            \'elapsed\':time.time()-start}\n', 'canal_23/cola_uv_BR0/motor_angulos.py': '"""Use reflection and canonical vertex caching; compare to the original motor."""\nimport numpy as np\nfrom stable_geometry import canonical\nimport polos_rapido as core\nfrom nucleo_uv import frame,HELS,exchange_parts,configuration,enc\n\nclass Kernel:\n    def __init__(self,order=24,cap_fraction=.35):\n        self.order=order;self.cap_fraction=cap_fraction;self.cache={}\n    def __call__(self,u,v):\n        u=np.asarray(u,float);v=np.asarray(v,float)\n        swap=(np.linalg.norm(u)<np.linalg.norm(v))\n        if swap:u,v=v,u\n        q=np.linalg.norm(u);r=np.linalg.norm(v)\n        s,uc,vc,rot=canonical(u,v)\n        # Keep the resolved transverse component in the cache identity.\n        key=tuple(uc)+tuple(vc)\n        if key not in self.cache:\n            raw=core.aligned_blocks(uc,vc,self.order,self.cap_fraction)\n            self.cache[key]=raw\n        raw=self.cache[key].copy()\n        phases=[]\n        for old,new in zip((u+v,u,v),(np.array([0.,0.,s]),uc,vc)):\n            old_m=rot@frame(old)[1];new_m=frame(new)[1]\n            z=new_m@old_m.conj();phases.append(z/abs(z))\n        basis=np.array([[phases[0]**ho*phases[1]**(-hu)*phases[2]**(-hv) for hu,hv in HELS] for ho in (2,-2)])\n        raw/=basis[:,:,None]\n        factor=2/np.sqrt(np.pi)*(s/(q*r))**1.5\n        tensor=np.zeros((2,2,2),complex)\n        for ih in range(2):\n            for j,(hu,hv) in enumerate(HELS):tensor[ih,int(hu<0),int(hv<0)]=factor*raw[ih,j].sum()\n        return tensor.swapaxes(1,2) if swap else tensor\n\ndef evaluate(E,mu,order=24,cap_fraction=.35):\n    k=Kernel(order,cap_fraction)\n    parts=exchange_parts(configuration(E/2,np.arccos(mu)),k)\n    m=parts[\'iteration\'];gas=m/(.25*E)\n    incoherent=sum(np.sum(abs(parts[c]/(.25*E))**2)/4 for c in [\'s\',\'t\',\'u\'])\n    return {\'E\':E,\'mu\':mu,\'order\':order,\'cap_fraction\':cap_fraction,\n            \'weight\':float(np.sum(abs(gas)**2)/4),\'matrix\':enc(m),\n            \'incoherent\':float(incoherent),\'canonical_vertices\':len(k.cache)}\n', 'canal_23/cola_uv_BR0/polos_rapido.py': '"""Circular finite-part diagnostic of the unfiltered five-block kernel.\n\nSmooth disjoint partitions around both daughter poles and the extraction pole.\nEvery cap is integrated down to zero radius: no cone is discarded. Azimuthal\naverages precede radial integration there. This implements a declared circular\nextension of the off-diagonal closed Greens, not a proof that heat regularization\nor the full NSF distributional prescription selects this extension.\n"""\nfrom functools import lru_cache\nimport numpy as np\nfrom scipy.special import roots_legendre\nfrom nucleo_uv import frame, HELS, exchange_parts, configuration, enc\n\nDIAGNOSTICS=[]\n# Reflection of the canonical planar geometry permits exact half-sphere integration.\n\n@lru_cache(None)\ndef gauss(n):return roots_legendre(n)\n\ndef bump(y):\n    a=np.clip((y-.25)/.75,0,1)\n    return 1-a*a*a*(10+a*(-15+6*a))\n\ndef green(n,m,nj,mj):\n    X=np.sum((n-nj)**2,axis=-1)/4\n    a=-(m@nj)/np.sqrt(2);b=-(n@mj)/np.sqrt(2);c=-(m@mj)\n    return (a*b-X*c)**2/(2*np.pi*X**3)\n\ndef dyad(n):\n    phi=np.arctan2(n[...,1],n[...,0]);st=np.hypot(n[...,0],n[...,1]);z=n[...,2]\n    return np.stack((z*np.cos(phi)-1j*np.sin(phi),z*np.sin(phi)+1j*np.cos(phi),-st),axis=-1)/np.sqrt(2)\n\ndef segment_grid(edges,order):\n    edges=sorted(set(float(e) for e in edges));q,w=gauss(order)\n    pts=[];weights=[]\n    for lo,hi in zip(edges[:-1],edges[1:]):\n        if not hi>lo:continue\n        pts.append((lo+hi)/2+(hi-lo)/2*q);weights.append((hi-lo)/2*w)\n    return np.concatenate(pts),np.concatenate(weights)\n\ndef aligned_blocks(pv,qv,order=16,cap_fraction=.35,shift=.173):\n    pv=np.asarray(pv,float);qv=np.asarray(qv,float)\n    p=np.linalg.norm(pv);q=np.linalg.norm(qv);s=np.linalg.norm(pv+qv)\n    ez=(pv+qv)/s;pz=float(pv@ez);perp=pv-pz*ez;px=np.linalg.norm(perp)\n    if px<=1e-14*max(p,q):raise ValueError(\'Exact collinear support requires its own distributional calculation\')\n    ex=perp/px;ey=np.cross(ez,ex);rotation=np.stack((ex,ey,ez))\n    u=np.array([px,0.,pz]);v=np.array([-px,0.,s-pz])\n    nu,mu=frame(u);nv,mv=frame(v);ns,ms=frame(np.array([0.,0.,s]))\n    dot=p*q*np.sum((pv/p-qv/q)**2)/2;defect=2*dot/(p+q+s)\n    if defect<=0:raise ValueError(\'Positive defect required\')\n    centers=[nu,nv,ns]\n    if not 0<cap_fraction<.5:raise ValueError(\'Disjoint caps require 0<fraction<1/2\')\n    # atan2 of cross/dot is stable for the small UV angular separations.\n    radii=[cap_fraction*min(np.arctan2(np.linalg.norm(np.cross(a,b)),a@b)\n                           for j,b in enumerate(centers) if j!=i)\n           for i,a in enumerate(centers)]\n    caps=[2*np.sin(r/2)**2 for r in radii]\n\n    def integrand(n):\n        m=dyad(n);z=n[...,2]\n        trans=n[...,0]**2+n[...,1]**2\n        t=trans/(1+z)\n        D=(defect+s*t)/np.sqrt(2)\n        C=p*q*np.sum((n-nu)**2,axis=-1)*np.sum((n-nv)**2,axis=-1)/8\n        A=(C/D)**2\n        R=(1+z)/(8*np.pi);Rp=1/(8*np.pi)\n        fr=R/D;fp=Rp/D+R*s/np.sqrt(2)/D**2\n        fpp=np.sqrt(2)*s*Rp/D**2+s*s*R/D**3\n        lap=trans*fpp-2*z*fp-4*fr/trans\n        h=green(n,m,nu,mu)*green(n,m,nv,mv).conj()\n        phase=(n[...,0]+1j*n[...,1])**2/trans\n        out=np.empty(n.shape[:-1]+(2,2,3),complex)\n        for ih,ph in enumerate((phase,phase.conj())):\n          for j,hh in enumerate((h,h.conj())):\n            out[...,ih,j,0]=2*lap*ph*C*hh\n            out[...,ih,j,1]=2*lap*ph*A*hh\n            out[...,ih,j,2]=dot*fr*ph*hh\n        return out\n\n    # Body quadrature resolves cap transitions plus the parent energy cone.\n    tedges=[0.,2.]\n    scale=max(defect/s,1e-14)\n    while scale<2:tedges.append(scale);scale*=2\n    phiedges=[0.,np.pi,2*np.pi]\n    for center,r in zip(centers,radii):\n        theta=np.arctan2(np.hypot(center[0],center[1]),center[2])\n        for a in [.5,1.,2.]:\n            tedges.extend([2*np.sin(max(0,theta-a*r)/2)**2,2*np.sin(min(np.pi,theta+a*r)/2)**2])\n        tedges.append(np.sum((center-ns)**2)/2)\n        if np.sin(theta)>1e-14:\n            width=min(r/np.sin(theta),np.pi/2)\n            while width<np.pi/2:\n                for origin in [0.,np.pi,2*np.pi]:\n                    phiedges.extend([a for a in [origin-width,origin+width] if 0<a<2*np.pi])\n                width*=2\n    tg,wx=segment_grid(tedges,order);phi,wp=segment_grid([a for a in phiedges if a<=np.pi],order)\n    body=np.zeros((2,2,3),complex);body_area=0.\n    for k in range(0,len(tg),16):\n        t=tg[k:k+16,None];z=1-t;st=np.sqrt(t*(2-t))\n        n=np.stack(np.broadcast_arrays(st*np.cos(phi),st*np.sin(phi),z),axis=-1)\n        chi=np.zeros(n.shape[:-1])\n        for c,tmax in zip(centers,caps):chi+=bump(np.sum((n-c)**2,axis=-1)/(2*tmax))\n        complement=np.maximum(0,1-chi)\n        body_area+=float(2*np.sum(wx[k:k+16,None]*wp[None,:]*complement))\n        body+=np.einsum(\'ab,abijk->ijk\',wx[k:k+16,None]*wp[None,:]*complement,2*integrand(n).real)\n    polar,wpolar=gauss(order)\n    nphi=4*order+8;phi=np.pi*(np.arange(nphi)+.5)/nphi\n    cap_values=[]\n    for c,tmax in zip(centers,caps):\n        t=tmax*(1+polar[:,None])/2\n        e1=np.array([c[2],0.,-c[0]]);e2=np.array([0.,1.,0.])\n        n=(1-t)[...,None]*c+np.sqrt(t*(2-t))[...,None]*(np.cos(phi)[...,None]*e1+np.sin(phi)[...,None]*e2)\n        # Angular mean first implements circular cancellation of leading poles.\n        avg=integrand(n).real.mean(axis=1)*2*np.pi\n        val=np.einsum(\'a,aijk->ijk\',wpolar*tmax/2*bump(t[:,0]/tmax),avg)\n        cap_values.append(val)\n    nonlocal_sum=body+sum(cap_values)\n    cap_area=sum(2*np.pi*np.sum(wpolar*tmax/2*bump((1+polar)/2)) for tmax in caps)\n    DIAGNOSTICS.append({\'order\':order,\'cap_fraction\':cap_fraction,\'radii\':radii,\n                        \'sphere_area_error\':float((body_area+cap_area)/(4*np.pi)-1)})\n    out=np.zeros((2,4,5),complex)\n    common=-1j*defect/(2*np.pi*np.sqrt(2)*s)\n    out[:,:2,:3]=.5*common*nonlocal_sum\n    pair=green(nu,mu,nv,mv)\n    for ih,mh in enumerate((ms,ms.conj())):\n        def f_at(c):\n            tr=c[0]**2+c[1]**2\n            return (1+c[2])/(8*np.pi)/((defect+s*tr/(1+c[2]))/np.sqrt(2))*2*(c@mh)**2/tr\n        out[ih,2,3]=.5*common*dot*f_at(nu)*pair.conjugate()\n        out[ih,2,4]=.5*common*dot*f_at(nv)*pair.conjugate()\n        out[ih,3,3]=.5*common*dot*f_at(nu)*pair\n        out[ih,3,4]=.5*common*dot*f_at(nv)*pair\n    phases=[]\n    for old,new in zip((pv+qv,pv,qv),(np.array([0.,0.,s]),u,v)):\n        old_m=rotation@frame(old)[1];new_m=frame(new)[1]\n        z=new_m@old_m.conj();phases.append(z/abs(z))\n    basis=np.array([[phases[0]**ho*phases[1]**(-hu)*phases[2]**(-hv) for hu,hv in HELS] for ho in (2,-2)])\n    return out/basis[:,:,None]\n\nclass Kernel:\n    def __init__(self,order=16,cap_fraction=.35,shift=.173):\n        self.order=order;self.cap_fraction=cap_fraction;self.shift=shift;self.cache={}\n    def __call__(self,u,v):\n        u=np.asarray(u,float);v=np.asarray(v,float);a=tuple(u);b=tuple(v);swap=a>b\n        key=(b,a) if swap else (a,b)\n        if key not in self.cache:\n            uu,vv=(v,u) if swap else (u,v)\n            src=aligned_blocks(uu,vv,self.order,self.cap_fraction,self.shift)\n            factor=2/np.sqrt(np.pi)*(np.linalg.norm(uu+vv)/(np.linalg.norm(uu)*np.linalg.norm(vv)))**1.5\n            tensor=np.zeros((2,2,2),complex)\n            for ih in range(2):\n                for j,(hu,hv) in enumerate(HELS):tensor[ih,int(hu<0),int(hv<0)]=factor*src[ih,j].sum()\n            self.cache[key]=tensor\n        out=self.cache[key]\n        return out.swapaxes(1,2) if swap else out\n\ndef evaluate(E,mu=.8,order=16,cap_fraction=.35,shift=.173):\n    parts=exchange_parts(configuration(E/2,np.arccos(mu)),Kernel(order,cap_fraction,shift))\n    m=parts[\'iteration\'];gas=m/(.25*E)\n    return {\'E\':E,\'mu\':mu,\'order\':order,\'cap_fraction\':cap_fraction,\'shift\':shift,\n            \'weight\':float(np.sum(abs(gas)**2)/4),\'matrix\':enc(m)}\n', 'canal_23/cola_uv_BR0/nucleo_uv.py': '"""Full five-block BCH aa kernel with a quadrature resolving the UV cone.\n\nSame finite heat projection as control_nucleo.vector_blocks, not a different\nkernel. Rotate the integration axis onto the parent; restore all helicity\nbasis phases. Piecewise Gauss quadrature resolves D=(E-s)+s(1-cos theta).\nContact BR=0 is an adopted BCH identity, not inferred from this integration.\n"""\nfrom functools import lru_cache\nfrom pathlib import Path\nimport sys\nimport numpy as np\nfrom scipy.special import roots_legendre, eval_jacobi\n\nROOT=Path(__file__).resolve().parent\nsys.path.insert(0,str(ROOT.parent/\'arbol_22_BCH\'))\nfrom amplitud_22 import exchange_parts, configuration, enc\nfrom control_nucleo import frame, g20_jet, HELS\n\n@lru_cache(None)\ndef gauss(order):\n    return roots_legendre(order)\n\ndef polar_grid(defect,s,order):\n    # t=1-cos(theta). Include exact integration endpoints but no pole node.\n    scale=max(defect/s,1e-15)\n    edges=[0.]\n    if scale<2:\n        t=scale\n        while t<2:\n            edges.append(t);t*=2\n    edges.append(2.)\n    q,w=gauss(order)\n    ts=[];ws=[]\n    for lo,hi in zip(edges[:-1],edges[1:]):\n        ts.append(.5*(hi-lo)*q+.5*(hi+lo))\n        ws.append(.5*(hi-lo)*w)\n    return 1-np.concatenate(ts),np.concatenate(ws)\n\ndef jacobi_series(x,L):\n    """Heat-filtered sum P_(ell-2)^(4,0), stable three-term recurrence."""\n    x=np.asarray(x,float)\n    p0=np.ones_like(x)\n    def coefficient(ell):\n        return (2*ell+1)/(4*np.pi)*np.exp(-16*ell*(ell+1)/L**2)\n    total=coefficient(2)*p0\n    if L==2:return total\n    p1=2+3*x\n    total+=coefficient(3)*p1\n    for k in range(2,L-1):\n        t=2*k+4\n        p=((t-1)*(t*(t-2)*x+16)*p1-2*(k+3)*(k-1)*t*p0)/(2*k*(k+4)*(t-2))\n        total+=coefficient(k+2)*p\n        p0,p1=p1,p\n    return total\n\ndef smooth_green(n,m,nj,mj,L):\n    x=np.clip(n@nj,-1,1)\n    X=(1-x)/2\n    a=-(m@nj)/np.sqrt(2);b=-(n@mj)/np.sqrt(2);c=-(m@mj)\n    return (a*b-X*c)**2*jacobi_series(x,L)\n\ndef aligned_blocks(pv,qv,L,order=None,nphi=None,shift=.173):\n    pv=np.asarray(pv,float);qv=np.asarray(qv,float)\n    s=np.linalg.norm(pv+qv);p=np.linalg.norm(pv);q=np.linalg.norm(qv)\n    ez=(pv+qv)/s\n    pz=float(pv@ez);perp=pv-pz*ez;px=np.linalg.norm(perp)\n    if px<=1e-14*max(p,q):\n        # No sampled UV or Gauss outgoing direction hits this exact support.\n        # Do not invent a limiting value for a coincident vertex.\n        raise ValueError(\'Exact collinear support requires the separate axial benchmark.\')\n    ex=perp/px;ey=np.cross(ez,ex);rotation=np.stack((ex,ey,ez))\n    u=np.array([px,0.,pz]);v=np.array([-px,0.,s-pz])\n    nu,mu=frame(u);nv,mv=frame(v);ns,ms=frame(np.array([0.,0.,s]))\n    # Stable E-s even in the hierarchical UV configuration.\n    cosuv=float(np.clip(pv@qv/(p*q),-1,1))\n    dot=p*q*(1-cosuv)\n    defect=2*dot/(p+q+s)\n    if defect<=0:raise ValueError(\'Positive noncollinear energy defect required\')\n    x,wx=polar_grid(defect,s,order or max(32,L+8))\n    nphi=nphi or 4*L+16\n    phi=2*np.pi*np.arange(nphi)/nphi+shift\n    xx=x[:,None];st=np.sqrt(1-xx*xx)\n    n=np.stack(np.broadcast_arrays(st*np.cos(phi),st*np.sin(phi),xx),axis=-1)\n    m=np.stack(np.broadcast_arrays(xx*np.cos(phi)-1j*np.sin(phi),xx*np.sin(phi)+1j*np.cos(phi),-st),axis=-1)/np.sqrt(2)\n    weights=wx[:,None]*2*np.pi/nphi\n    g1=smooth_green(n,m,nu,mu,L);g2=smooth_green(n,m,nv,mv,L)\n    h=g1*g2.conj()\n    D=(defect+s*(1-x))[:,None]/np.sqrt(2)\n    D1=(p-n@u)/np.sqrt(2);D2=(q-n@v)/np.sqrt(2)\n    contact=D1*D2;affine=(contact/D)**2\n    R,Rp,Rpp=(z[:,None] for z in g20_jet(x,L))\n    fr=R/D;fp=Rp/D+R*s/np.sqrt(2)/D**2\n    fpp=Rpp/D+np.sqrt(2)*s*Rp/D**2+s*s*R/D**3\n    lapfr=(1-xx*xx)*fpp-2*xx*fp-4*fr/(1-xx*xx)\n    common=-1j*defect/(2*np.pi*np.sqrt(2)*s)\n    out=np.zeros((2,4,5),complex)\n    for ih,hout in enumerate((2,-2)):\n        mh=ms if hout==2 else ms.conj()\n        phase=2*(n@mh)**2/(1-xx*xx)\n        f=fr*phase;lapf=lapfr*phase\n        for j,hh in enumerate((h,h.conj())):\n            out[ih,j,0]=.5*common*np.sum(weights*2*lapf*contact*hh)\n            out[ih,j,1]=.5*common*np.sum(weights*2*lapf*affine*hh)\n            out[ih,j,2]=.5*common*dot*np.sum(weights*f*hh)\n        def f_at(nj):\n            z=float(nj[2])\n            if abs(1-z*z)<1e-14:return 0j\n            return g20_jet(np.array(z),L)[0]/((defect+s*(1-z))/np.sqrt(2))*2*(nj@mh)**2/(1-z*z)\n        pair=smooth_green(nu,mu,nv,mv,L)\n        out[ih,2,3]=.5*common*dot*f_at(nu)*pair.conjugate()\n        out[ih,2,4]=.5*common*dot*f_at(nv)*pair.conjugate()\n        out[ih,3,3]=.5*common*dot*f_at(nu)*pair\n        out[ih,3,4]=.5*common*dot*f_at(nv)*pair\n    phases=[]\n    for old,new in zip((pv+qv,pv,qv),(np.array([0.,0.,s]),u,v)):\n        old_m=rotation@frame(old)[1];new_m=frame(new)[1]\n        z=new_m@old_m.conj();phases.append(z/abs(z))\n    basis=np.array([[phases[0]**ho*phases[1]**(-hu)*phases[2]**(-hv) for hu,hv in HELS] for ho in (2,-2)])\n    out/=basis[:,:,None]\n    return out\n\nclass UVKernel:\n    def __init__(self,L=24,order=None,nphi=None,shift=.173):\n        self.L=L;self.order=order;self.nphi=nphi;self.shift=shift;self.cache={}\n    def __call__(self,u,v):\n        u=np.asarray(u,float);v=np.asarray(v,float)\n        a=tuple(u);b=tuple(v);swap=a>b;key=(b,a) if swap else (a,b)\n        if key not in self.cache:\n            uu,vv=(v,u) if swap else (u,v)\n            source=aligned_blocks(uu,vv,self.L,self.order,self.nphi,self.shift)\n            p=np.linalg.norm(uu+vv);q=np.linalg.norm(uu);r=np.linalg.norm(vv)\n            factor=2/np.sqrt(np.pi)*(p/(q*r))**1.5\n            tensor=np.zeros((2,2,2),complex)\n            for ih in range(2):\n                for j,(hu,hv) in enumerate(HELS):tensor[ih,int(hu<0),int(hv<0)]=factor*source[ih,j].sum()\n            self.cache[key]=tensor\n        out=self.cache[key]\n        return out.swapaxes(1,2) if swap else out\n\ndef evaluate(r,mu,L=24,order=None,nphi=None,shift=.173):\n    vectors=configuration(r,np.arccos(mu))\n    parts=exchange_parts(vectors,UVKernel(L,order,nphi,shift))\n    m=parts[\'iteration\']\n    # Initial E_i=1, each frequency .5; final frequencies r,r.\n    gas=m/(.5*r)\n    unpolarized=float(np.sum(abs(gas)**2)/4)\n    incoherent=float(sum(np.sum(abs(parts[c]/(.5*r))**2)/4 for c in (\'s\',\'t\',\'u\')))\n    return {\'r\':float(r),\'Ef\':float(2*r),\'mu\':float(mu),\'L\':L,\n            \'unpolarized_reduced_weight\':unpolarized,\'incoherent_reduced_weight\':incoherent,\n            \'interference_reduced_weight\':unpolarized-incoherent,\n            \'matrix_reduced_a\':enc(m),\'max_abs_reduced_a\':float(np.max(abs(m)))}\n', 'canal_23/arbol_22_BCH/amplitud_22.py': '"""Leading connected 2->2 assembler using the current physical T1 kernel.\n\nThe independent cubic NSF B source is REQUIRED for a full amplitude. No\ndefault-zero contact. Results produced by main are T1 iterations plus the\nBCH subtraction, never a claimed complete physical scattering probability.\n"""\nfrom pathlib import Path\nimport sys,json,itertools,hashlib\nimport numpy as np\nimport mpmath as mp\n\nROOT=Path(__file__).resolve().parent\nsys.path.insert(0,str(ROOT.parent/\'control_nucleo_etapa1\'))\nsys.path.insert(0,str(ROOT.parent/\'control_fisico_WFD\'))\nfrom control_nucleo import vector_blocks,HELS,rotation_matrix,frame\nfrom calcular_WFD import mode_factor,nu0,mono,add,scale,adj,mul,comm,action\n\nPAIRS=[(0,0),(0,1),(1,0),(1,1)]\nASSIGNMENTS=[(2,0,1,3),(2,1,0,3),(3,0,1,2),(3,1,0,2)]\n\ndef cubic_mode_factor(q,r,u,v):\n    """Independent source B0=2wq nu0(r)nu0(u)nu0(v)/nu0(q) * V3.\n\n    Here V3 is exactly the reduced third-order vertex of QS-II (192)-(193),\n    not the old quadratic extraction coefficient. Signed momenta/helicities\n    belong inside V3; all four weights use positive physical frequencies.\n    """\n    return 2*mp.mpf(q)*nu0(r)*nu0(u)*nu0(v)/nu0(q)\n\ndef enc(a):\n    a=np.asarray(a,complex);return np.stack([a.real,a.imag],axis=-1).tolist()\n\nclass Kernel:\n    def __init__(self,L=24,grid_multiplier=1):self.L=L;self.grid_multiplier=grid_multiplier;self.cache={}\n    def __call__(self,u,v):\n        u=np.asarray(u,float);v=np.asarray(v,float)\n        if min(np.linalg.norm(u),np.linalg.norm(v),np.linalg.norm(u+v))<=0:raise ValueError(\'Zero mode is excluded, never evaluated.\')\n        a=tuple(np.round(u,14));b=tuple(np.round(v,14));swapped=a>b\n        key=(b,a) if swapped else (a,b)\n        if key not in self.cache:\n            uu,vv=(v,u) if swapped else (u,v)\n            source=vector_blocks(uu,vv,self.L,nx=self.grid_multiplier*(6*self.L+24),nphi=self.grid_multiplier*(8*self.L+48))\n            factor=float(mode_factor(str(np.linalg.norm(uu+vv)),str(np.linalg.norm(uu)),str(np.linalg.norm(vv))))\n            tensor=np.zeros((2,2,2),complex)\n            for ih,h in enumerate((2,-2)):\n                for j,(hu,hv) in enumerate(HELS):tensor[ih,int(hu<0),int(hv<0)]=factor*source[ih,j].sum()\n            self.cache[key]=tensor\n        out=self.cache[key]\n        return out.swapaxes(1,2) if swapped else out\n\ndef exchange_parts(vectors,kernel):\n    v=np.asarray(vectors,float)\n    if v.shape!=(4,3) or not np.allclose(v[0]+v[1],v[2]+v[3],rtol=0,atol=1e-12):raise ValueError(\'Four momenta with spatial conservation are required.\')\n    if np.min(np.linalg.norm(v,axis=1))<=0:raise ValueError(\'All external frequencies positive.\')\n    fusion=np.zeros((4,4),complex);ex=np.zeros((4,4,4),complex)\n    p=v[0]+v[1];excluded=[]\n    if np.linalg.norm(p)>0:\n        ki,ko=kernel(v[0],v[1]),kernel(v[2],v[3])\n        for o,(h3,h4) in enumerate(PAIRS):\n            for i,(h1,h2) in enumerate(PAIRS):fusion[o,i]=np.vdot(ko[:,h3,h4],ki[:,h1,h2])/(2*np.linalg.norm(p))\n    else:excluded.append(\'s: exact internal zero mode\')\n    for a,(po,di,pi,do) in enumerate(ASSIGNMENTS):\n        r=v[po]-v[di]\n        if np.linalg.norm(r)==0:excluded.append(\'exchange assignment \'+str(a)+\': exact internal zero mode\');continue\n        left,right=kernel(r,v[di]),kernel(r,v[do])\n        for o,hf in enumerate(PAIRS):\n            for i,hi in enumerate(PAIRS):\n                h=hi+hf\n                ex[a,o,i]=sum(left[h[po],hr,h[di]]*right[h[pi],hr,h[do]].conjugate() for hr in (0,1))/(2*np.linalg.norm(r))\n    return {\'s\':-.25*fusion,\'t\':-.25*(ex[0]+ex[3]),\'u\':-.25*(ex[1]+ex[2]),\'iteration\':-.25*(fusion+ex.sum(0)),\n            \'resolved_fusion\':fusion,\'resolved_exchange_assignments\':ex,\'excluded\':excluded}\n\ndef iteration_B_formula(vectors,kernel):\n    """BCH (82) symmetrized over the inputs = the expression printed A.26.\n\n    Reduced B0 convention: dmu0^3 delta3 times B0 a_creator† a_in a_in.\n    Each resolved internal line contributes 1/(2 omega_r).\n    """\n    v=np.asarray(vectors,float);results=[]\n    for qindex,cindex in ((2,3),(3,2)):\n        b=np.zeros((4,4),complex)\n        for o,hf in enumerate(PAIRS):\n          for i,hi in enumerate(PAIRS):\n            hs=hi+hf;hq,hc=hs[qindex],hs[cindex];z=0j\n            for a,other in ((0,1),(1,0)):\n                r=v[qindex]-v[a]\n                if np.linalg.norm(r)>0:\n                    left,right=kernel(v[a],r),kernel(r,v[cindex])\n                    z-=sum(left[hq,hs[a],hr]*right[hs[other],hr,hc].conjugate() for hr in (0,1))/(2*np.linalg.norm(r))\n                r=v[other]-v[qindex]\n                if np.linalg.norm(r)>0:\n                    left,right=kernel(v[qindex],r),kernel(r,v[a])\n                    z+=sum(left[hs[other],hq,hr].conjugate()*right[hc,hr,hs[a]] for hr in (0,1))/(2*np.linalg.norm(r))\n            r=v[0]+v[1]\n            if np.linalg.norm(r)>0:\n                left,right=kernel(v[qindex],v[cindex]),kernel(v[0],v[1])\n                z-=sum(left[hr,hq,hc].conjugate()*right[hr,hi[0],hi[1]] for hr in (0,1))/(2*np.linalg.norm(r))\n            b[o,i]=z\n        results.append(b)\n    return results[0],results[1],.5*(results[0]+results[1])\n\ndef assemble_complete(vectors,kernel,B_qr=None,B_rq=None,source_record=None):\n    """A true independent B source is mandatory, in SAME external helicity basis.\n\n    B0 includes mode factors, no spatial delta, measure dmu0. B_qr/B_rq\n    are the two outgoing orderings, after incoming Bose symmetrization.\n    source_record must describe formula and regularization; it is provenance,\n    NOT numerical validation. Supplying an arbitrary matrix does not validate B.\n    """\n    if B_qr is None or B_rq is None:raise ValueError(\'Full amplitude unavailable: independent physical cubic B(q,r|1,2) is required. The BCH iteration I_B is not that input.\')\n    if not source_record:raise ValueError(\'Describe the independent source formula, mode factors and regulator.\')\n    b1,b2=np.asarray(B_qr,complex),np.asarray(B_rq,complex)\n    if b1.shape!=(4,4) or b2.shape!=(4,4):raise ValueError(\'B orderings must be 4x4 matrices: final rows, initial columns (++,+-,-+,--).\')\n    ex=exchange_parts(vectors,kernel);i1,i2,isym=iteration_B_formula(vectors,kernel)\n    residual=.5*(b1+b2-i1-i2);contact=.25*residual;total=contact+ex[\'iteration\']\n    w=np.linalg.norm(np.asarray(vectors),axis=1);cell_factor=1/np.sqrt(np.prod(w))\n    return {\'contact_reduced_a\':contact,\'iteration_reduced_a\':ex[\'iteration\'],\'total_reduced_a\':total,\n            \'BR_reduced_a\':residual,\'IB_sym\':isym,\n            \'contact_square\':abs(contact)**2,\'iteration_square\':abs(ex[\'iteration\'])**2,\n            \'interference\':2*np.real(contact*ex[\'iteration\'].conjugate()),\'total_square\':abs(total)**2,\n            \'Gasiorowicz_one_delta_coefficient\':total*cell_factor,\n            \'normalized_box_amplitude_per_cell\':total*cell_factor,\'source_record\':source_record}\n\ndef stencil(vectors,kernel,cell=mp.mpf(\'.000125\')):\n    """Independent direct canonical Fock operator with every required vertex."""\n    vectors=np.asarray(vectors,float);momenta=[];keys={}\n    def register(p):\n        key=tuple(np.round(p,14))\n        if key not in keys:keys[key]=len(momenta);momenta.append(np.asarray(p,float))\n        return keys[key]\n    external=[register(p) for p in vectors];vertices={}\n    p=vectors[0]+vectors[1]\n    if np.linalg.norm(p)>0:\n        parent=register(p)\n        for u,v in ((0,1),(2,3)):vertices[parent,external[u],external[v]]=kernel(vectors[u],vectors[v])\n    for po,di,pi,do in ASSIGNMENTS:\n        r=vectors[po]-vectors[di]\n        if np.linalg.norm(r)==0:continue\n        internal=register(r)\n        for parent,daughter in ((po,di),(pi,do)):\n            vertices[external[parent],internal,external[daughter]]=kernel(r,vectors[daughter])\n    n=2*len(momenta);w=[mp.mpf(str(np.linalg.norm(p))) for p in momenta for _ in range(2)];A={}\n    for (p,u,v),tensor in vertices.items():\n        for hp,hu,hv in itertools.product((0,1),repeat=3):\n            pp,uu,vv=2*p+hp,2*u+hu,2*v+hv\n            k=mp.mpc(float(tensor[hp,hu,hv].real),float(tensor[hp,hu,hv].imag))\n            gamma=-1j*mp.sqrt(cell)*k/(2*mp.sqrt(w[pp]*w[uu]*w[vv]))\n            A=add(A,scale(mono(n,(pp,),(uu,vv)),gamma))\n    return add(A,adj(A)),w,external,momenta\n\ndef direct_iteration_and_IB(vectors,kernel,cell=\'.000125\'):\n    with mp.workdps(50):\n        cell=mp.mpf(cell);T,w,indices,momenta=stencil(vectors,kernel,cell);n=len(w)\n        normfreq=mp.sqrt(mp.fprod(mp.mpf(str(x)) for x in np.linalg.norm(vectors,axis=1)))\n        matrix=np.zeros((4,4),complex);ib1=np.zeros_like(matrix);ib2=np.zeros_like(matrix)\n        sources={}\n        for e in (2,3):\n            for h in (0,1):\n                j=2*indices[e]+h;c=mono(n,(),(j,))\n                sources[e,h]=scale(comm(comm(c,T),T),-mp.mpf(\'.5\'))\n        for i,hi in enumerate(PAIRS):\n            occ=[0]*n;occ[2*indices[0]+hi[0]]=1;occ[2*indices[1]+hi[1]]=1\n            first=action(T,occ);second={}\n            for state,z in first.items():\n                for final,z2 in action(T,state).items():second[final]=second.get(final,mp.mpc(0))+z*z2\n            for o,hf in enumerate(PAIRS):\n                final=[0]*n;final[2*indices[2]+hf[0]]=1;final[2*indices[3]+hf[1]]=1\n                matrix[o,i]=complex(-mp.mpf(\'.5\')*second.get(tuple(final),mp.mpc(0))*normfreq/cell)\n                for q,c,hm,store in ((2,3,hf[0],ib1),(3,2,hf[1],ib2)):\n                    creator=2*indices[c]+hf[c-2]\n                    key=next(iter(mono(n,(creator,),(2*indices[0]+hi[0],2*indices[1]+hi[1]))))\n                    coef=sources[q,hm].get(key,mp.mpc(0))\n                    store[o,i]=complex(4*normfreq/cell*coef)\n        return matrix,ib1,ib2,{\'canonical_modes\':n,\'momentum_nodes\':len(momenta),\'vertices\':len(T),\'cell\':str(cell)}\n\ndef contact_lift_audit():\n    """Synthetic T2 ONLY to test lifting and interference, no physical claim."""\n    rng=np.random.default_rng(191);BR=rng.normal(size=(4,4))+1j*rng.normal(size=(4,4))\n    with mp.workdps(70):\n        cell=mp.mpf(\'.015625\');w=[mp.mpf(\'.5\')]*4+[mp.mpf(\'.75\')]*4;nf=mp.sqrt(mp.mpf(\'.5\')**2*mp.mpf(\'.75\')**2)\n        T={}\n        for o,hf in enumerate(PAIRS):\n            for i,hi in enumerate(PAIRS):\n                c=mp.mpc(float(BR[o,i].real),float(BR[o,i].imag));g=-1j*cell*c/(4*nf)\n                p=scale(mono(8,(4+hf[0],6+hf[1]),(hi[0],2+hi[1])),g);T=add(T,p,adj(p))\n        error=mp.mpf(0);rerror=mp.mpf(0)\n        for i,hi in enumerate(PAIRS):\n            occ=[0]*8;occ[hi[0]]=1;occ[2+hi[1]]=1;psi=action(T,occ)\n            for o,hf in enumerate(PAIRS):\n                final=[0]*8;final[4+hf[0]]=1;final[6+hf[1]]=1\n                direct=1j*psi[tuple(final)];expected=cell/(4*nf)*mp.mpc(float(BR[o,i].real),float(BR[o,i].imag))\n                error=max(error,abs(direct-expected))\n                reverse=action(T,final).get(tuple(occ),mp.mpc(0));rerror=max(rerror,abs(1j*reverse+mp.conj(direct)))\n        assert error<mp.mpf(\'1e-65\') and rerror<mp.mpf(\'1e-65\')\n        return {\'scope\':\'SYNTHETIC quartic operator, algebra/normalization only, NOT NSF contact\', \'max_lift_error\':mp.nstr(error,25),\'contact_antihermitian_reverse_error\':mp.nstr(rerror,25)}\n\ndef full_synthetic_audit(vectors,kernel):\n    """Independent T2 Fock action plus real T1; verifies coherent assembly."""\n    rng=np.random.default_rng(3821);BR=rng.normal(size=(4,4))+1j*rng.normal(size=(4,4))\n    i1,i2,_=iteration_B_formula(vectors,kernel)\n    assembled=assemble_complete(vectors,kernel,i1+BR,i2+BR,source_record=\'SYNTHETIC independent Hermitian quartic generator; NOT NSF contact\')\n    with mp.workdps(60):\n        cell=mp.mpf(\'.000125\');T1,w,indices,_=stencil(vectors,kernel,cell);n=len(w);T2={}\n        nf=mp.sqrt(mp.fprod(mp.mpf(str(x)) for x in np.linalg.norm(vectors,axis=1)))\n        for o,hf in enumerate(PAIRS):\n            for i,hi in enumerate(PAIRS):\n                g=-1j*cell/(4*nf)*mp.mpc(float(BR[o,i].real),float(BR[o,i].imag))\n                p=scale(mono(n,(2*indices[2]+hf[0],2*indices[3]+hf[1]),(2*indices[0]+hi[0],2*indices[1]+hi[1])),g)\n                T2=add(T2,p,adj(p))\n        error=mp.mpf(0)\n        for i,hi in enumerate(PAIRS):\n            occ=[0]*n;occ[2*indices[0]+hi[0]]=1;occ[2*indices[1]+hi[1]]=1\n            t2=action(T2,occ);t11={}\n            for state,z in action(T1,occ).items():\n                for final,z2 in action(T1,state).items():t11[final]=t11.get(final,mp.mpc(0))+z*z2\n            for o,hf in enumerate(PAIRS):\n                final=[0]*n;final[2*indices[2]+hf[0]]=1;final[2*indices[3]+hf[1]]=1\n                direct=(1j*t2.get(tuple(final),mp.mpc(0))-.5*t11.get(tuple(final),mp.mpc(0)))*nf/cell\n                error=max(error,abs(direct-complex(assembled[\'total_reduced_a\'][o,i])))\n        squares=assembled[\'contact_square\']+assembled[\'iteration_square\']+assembled[\'interference\']\n        square_error=float(np.max(abs(squares-assembled[\'total_square\'])))\n        assert error<mp.mpf(\'1e-14\') and square_error<1e-14\n        return {\'scope\':\'SYNTHETIC contact; real T1 provider. No physical total amplitude inferred.\',\n           \'direct_S2_vs_assembled_max_error\':mp.nstr(error,25),\'coherent_square_vs_three_blocks_error\':square_error}\n\ndef configuration(r=.5,theta=None):\n    # Rational direction: every moment is compatible with a .05 lattice.\n    n=np.array([.6,0.,.8]) if theta is None else np.array([np.sin(theta),0,np.cos(theta)])\n    return np.array([[0,0,.5],[0,0,-.5],r*n,-r*n])\n\ndef main():\n    data={\'status\':\'INCOMPLETE_PHYSICAL_CONTACT; numerical data are iterations and BCH subtraction only\',\n          \'chosen_contact_source\':\'Independent cubic NSF source from Quantum II; A.26 is retained only as the iteration audit.\',\n          \'normalization\':\'Current BCH nu0(w)=sqrt(4piG)/pi*w^(-3/2), G=1; dmu0; Gasiorowicz external states\',\n          \'matrix_order\':\'rows outgoing, columns incoming: (++,+-,-+,--)\',\n          \'complete_formula\':\'m_red_a=(B_sym-I_B_sym)/4 + m_iteration; M_box=v*m_red_a/sqrt(w1w2w3w4)\',\n          \'contact_source_audit\':\'The formula in BCH A.26 coincides term by term with incoming-symmetrized I_B from Eq.(82); using it as the independent full B forces B_R=0 identically. No physical zero contact is assumed.\',\n          \'physical_contact_missing\':\'Independent flat-cone cubic B (NSF third-order source), including conformal Omega3 and lower Lambda2 coefficients, mapped to both outgoing helicity bases with a common PV prescription.\',\n          \'points\':[]}\n    for L,r in itertools.product((12,24),(.25,.5,1.)):\n        vectors=configuration(r);kernel=Kernel(L);parts=exchange_parts(vectors,kernel)\n        b1,b2,bs=iteration_B_formula(vectors,kernel)\n        direct,d1,d2,st=direct_iteration_and_IB(vectors,kernel)\n        err=float(np.max(abs(parts[\'iteration\']-direct)));iberr=float(max(np.max(abs(b1-d1)),np.max(abs(b2-d2))))\n        scale0=max(np.max(abs(parts[\'iteration\'])),np.max(abs(b1)),np.max(abs(b2)),1e-30)\n        assert err/scale0<1e-11 and iberr/scale0<1e-11,(L,r,err,iberr,scale0)\n        record={\'L\':L,\'outgoing_frequency\':r,\'outgoing_total_energy\':2*r,\'incoming_total_energy\':1.,\'theta_degrees\':float(np.degrees(np.arctan2(3,4))),\'vectors\':vectors.tolist(),\n            \'iteration\':enc(parts[\'iteration\']),\'s\':enc(parts[\'s\']),\'t\':enc(parts[\'t\']),\'u\':enc(parts[\'u\']),\n            \'I_B_qr\':enc(b1),\'I_B_rq\':enc(b2),\'I_B_sym\':enc(bs),\'known_affine_part\':enc(parts[\'iteration\']-.25*bs),\n            \'excluded\':parts[\'excluded\'],\'direct_Fock_vs_iteration_error\':err,\'direct_double_commutator_vs_IB_error\':iberr,\n            \'relative_verification_error\':max(err,iberr)/scale0,\'stencil\':st,\'cached_kernel_pairs\':len(kernel.cache),\n            \'iteration_square_only\':(abs(parts[\'iteration\'])**2).tolist()}\n        data[\'points\'].append(record)\n        print(\'iteration\',L,r,\'max\',float(np.max(abs(parts[\'iteration\']))),\'Fock error\',err,\'IB error\',iberr,flush=True)\n    data[\'synthetic_contact_lift_audit\']=contact_lift_audit()\n    # Non-CoM audit exercises the NONZERO s routing as well as all exchanges.\n    generic=np.array([[0,0,.5],[.5,0,0],[.3,0,.4],[.2,0,.1]])\n    k=Kernel(12);ex=exchange_parts(generic,k);i1,i2,isy=iteration_B_formula(generic,k)\n    dr,d1,d2,st=direct_iteration_and_IB(generic,k)\n    error=float(max(np.max(abs(ex[\'iteration\']-dr)),np.max(abs(i1-d1)),np.max(abs(i2-d2))))\n    assert error<1e-10\n    data[\'generic_all_channels_audit\']={\'vectors\':generic.tolist(),\'L\':12,\'iteration\':enc(ex[\'iteration\']), \'I_B_qr\':enc(i1),\'I_B_rq\':enc(i2),\n        \'I_B_sym\':enc(isy),\'s\':enc(ex[\'s\']),\'max_direct_error\':error,\'sym_IB_plus_fusion_error\':float(np.max(abs(isy+ex[\'resolved_fusion\']))),\'stencil\':st}\n    data[\'full_synthetic_audit\']=full_synthetic_audit(generic,k)\n    data[\'independent_cubic_source_dictionary\']=\'B0=2wq*nu0(r)nu0(1)nu0(2)/nu0(q) * (V3_+-(q;1,2,r)+V3_-+(q;1,r,2))_(12), with signed momenta/helicity labels inside V3; dmu0^3 delta3, no extra spatial delta in B0\'\n    # Refinement changes quadrature, not the finite Green filter.\n    v=configuration(.5);fine=Kernel(24,2);refined=exchange_parts(v,fine)[\'iteration\']\n    base=data[\'points\'][4];old=np.array(base[\'iteration\']);old=old[...,0]+1j*old[...,1]\n    data[\'grid_doubling_L24_Ef1_max_difference\']=float(np.max(abs(old-refined)))\n    assert data[\'grid_doubling_L24_Ef1_max_difference\']<1e-10\n    # Ensure the API does not turn unavailable contact into zero.\n    try:assemble_complete(v,Kernel(12))\n    except ValueError as e:data[\'missing_contact_guard\']=str(e)\n    else:raise AssertionError(\'Missing contact accepted silently.\')\n    data[\'source_hashes\']={}\n    for p in [Path(__file__),ROOT.parent/\'control_fisico_WFD/calcular_WFD.py\',ROOT.parents[1]/\'sources/BCH_Reconstruction_in_Quantum_NSF(2).pdf\',ROOT.parents[1]/\'upload/Quantum_scattering_II_revised_final(1).pdf\']:\n        if p.exists():data[\'source_hashes\'][str(p.relative_to(ROOT.parents[1]))]=hashlib.sha256(p.read_bytes()).hexdigest()\n    (ROOT/\'resultados_arbol_22.json\').write_text(json.dumps(data,indent=2)+\'\\n\')\n    print(json.dumps({\'status\':data[\'status\'],\'grid_difference\':data[\'grid_doubling_L24_Ef1_max_difference\'],\'contact_lift\':data[\'synthetic_contact_lift_audit\']},indent=2))\n\nif __name__==\'__main__\':main()\n', 'canal_23/control_nucleo_etapa1/control_nucleo.py': '"""Stage-I angular benchmark. Geometric aa kernel, NOT normalized T1 or a probability.\n\nAll nonlocal Green functions, including external G20, use the same finite\nheat projection. Local deltas are integrated exactly. No energy delta.\nRun python3 control_nucleo.py; numpy, scipy, mpmath required.\n"""\nfrom pathlib import Path\nimport sys, json, itertools, hashlib, time\nimport numpy as np\nimport mpmath as mp\nimport math\nfrom scipy.special import eval_jacobi, lpmv, gammaln\nfrom numpy.polynomial.legendre import leggauss\n\nROOT=Path(__file__).resolve().parent\nPREVIOUS=ROOT.parent/\'deltaE_nucleo_completo\'\nsys.path.insert(0,str(PREVIOUS))\nfrom calcular_deltaE import greens, run as previous_run\n\nBLOCKS=[\'Omega_contact\',\'Omega_affine\',\'Lambda_bilocal\',\'Lambda_local_1\',\'Lambda_local_2\']\nHELS=[(-2,2),(2,-2),(2,2),(-2,-2)]\n\ndef encode(z):\n    a=np.asarray(z); return np.stack([a.real,a.imag],axis=-1).tolist()\n\ndef frame(v):\n    n=np.asarray(v,float); n=n/np.linalg.norm(n)\n    phi=np.arctan2(n[1],n[0]) if np.hypot(n[0],n[1])>1e-14 else 0.\n    st=np.hypot(n[0],n[1]); ct=n[2]\n    m=np.array([ct*np.cos(phi)-1j*np.sin(phi),ct*np.sin(phi)+1j*np.cos(phi),-st])/np.sqrt(2)\n    return n,m\n\ndef g20_jet(x,L):\n    out=[np.zeros_like(x) for _ in range(3)]\n    for ell in range(2,L+1):\n        n=ell-2\n        c=(2*ell+1)/(4*np.pi)*np.exp(-16*ell*(ell+1)/L**2)*(ell+1)*(ell+2)/(4*((ell-1)*ell*(ell+1)*(ell+2)))\n        J=eval_jacobi(n,2,2,x)\n        Jp=(n+5)/2*eval_jacobi(n-1,3,3,x) if n>=1 else np.zeros_like(x)\n        Jpp=(n+5)*(n+6)/4*eval_jacobi(n-2,4,4,x) if n>=2 else np.zeros_like(x)\n        out[0]+=c*(1-x*x)*J\n        out[1]+=c*(-2*x*J+(1-x*x)*Jp)\n        out[2]+=c*(-2*J-4*x*Jp+(1-x*x)*Jpp)\n    return out\n\ndef green22(n,m,nj,mj,L):\n    x=np.clip(n@nj,-1.,1.); X=(1-x)/2\n    A=-(m@nj)/np.sqrt(2); B=-(n@mj)/np.sqrt(2); C=-(m@mj)\n    num=(A*B-X*C)**2\n    phase=np.divide(num,np.abs(num),out=np.zeros_like(num),where=np.abs(num)>1e-290)\n    return greens(x,L)[0]*phase\n\ndef scalar_laplacian(values,x,wx,ellmax):\n    """Independent source derivative by spherical harmonic projection."""\n    nphi=values.shape[1]\n    ft=np.fft.fft(values,axis=1)/nphi; out=np.zeros_like(ft)\n    for m in range(ellmax+1):\n        ls=np.arange(m,ellmax+1)\n        harmonics=np.array([np.exp(.5*(np.log((2*l+1)/(4*np.pi))+gammaln(l-m+1)-gammaln(l+m+1)))*lpmv(m,l,x) for l in ls])\n        for j in ([0] if m==0 else [m,-m]):\n            c=2*np.pi*(harmonics@(wx*ft[:,j]))\n            out[:,j]=(-ls*(ls+1)*c)@harmonics\n    return np.fft.ifft(out*nphi,axis=1)\n\ndef vector_blocks(pv,qv,L,nx=None,nphi=None,shift=.173,basis=(0.,0.,0.),route=\'external\',ellmax=None):\n    """Full five aa blocks in fixed Cartesian coordinates, both helicities.\n\n    External route transfers the scalar Laplacian onto the smooth projected\n    extraction Green. Source route differentiates the source spectrally.\n    Polarization basis rotations enter explicit tangent dyads, not a fitted phase.\n    """\n    nx=nx or 6*L+24; nphi=nphi or 8*L+48\n    x,wx=leggauss(nx); phi=2*np.pi*np.arange(nphi)/nphi+shift\n    xx=x[:,None]; st=np.sqrt(1-xx*xx)\n    n=np.stack(np.broadcast_arrays(st*np.cos(phi),st*np.sin(phi),xx),axis=-1)\n    m=np.stack(np.broadcast_arrays(xx*np.cos(phi)-1j*np.sin(phi),xx*np.sin(phi)+1j*np.cos(phi),-st),axis=-1)/np.sqrt(2)\n    weights=wx[:,None]*2*np.pi/nphi\n    pv=np.asarray(pv,float);qv=np.asarray(qv,float);sv=pv+qv\n    p=np.linalg.norm(pv);q=np.linalg.norm(qv);s=np.linalg.norm(sv);E=p+q\n    assert min(p,q,s)>0 and E>s\n    ns,ms=frame(sv);np_,mp_=frame(pv);nq,mq=frame(qv)\n    ms*=np.exp(1j*basis[0]);mp_*=np.exp(1j*basis[1]);mq*=np.exp(1j*basis[2])\n    g1=green22(n,m,np_,mp_,L);g2=green22(n,m,nq,mq,L)\n    h=g1*g2.conj()\n    z=np.clip(n@ns,-1.,1.); D=(E-s*z)/np.sqrt(2)\n    D1=(p-n@pv)/np.sqrt(2);D2=(q-n@qv)/np.sqrt(2)\n    contact=D1*D2;affine=(contact/D)**2; dot=p*q-pv@qv\n    R,Rp,Rpp=g20_jet(z,L)\n    fr=R/D; fp=Rp/D+R*s/np.sqrt(2)/D**2\n    fpp=Rpp/D+np.sqrt(2)*s*Rp/D**2+s*s*R/D**3\n    lapfr=(1-z*z)*fpp-2*z*fp-4*fr/(1-z*z)\n    common=-1j*(E-s)/(2*np.pi*np.sqrt(2)*s)\n    out=np.zeros((2,4,5),complex)\n    for ih,hout in enumerate((2,-2)):\n        mh=ms if hout==2 else ms.conj()\n        phase=2*(n@mh)**2/(1-z*z)\n        f=fr*phase; lapf=lapfr*phase\n        for j,hh in enumerate((h,h.conj())):\n            for b,F in enumerate((contact,affine)):\n                if route==\'external\': integrand=2*lapf*F*hh\n                else: integrand=2*f*scalar_laplacian(F*hh,x,wx,ellmax or (2*L+24))\n                out[ih,j,b]=.5*common*np.sum(weights*integrand)\n            out[ih,j,2]=.5*common*dot*np.sum(weights*f*hh)\n        def f_at(nj):\n            zj=float(ns@nj)\n            if abs(1-zj*zj)<1e-14:return 0j\n            return g20_jet(np.array(zj),L)[0]/((E-s*zj)/np.sqrt(2))*2*(nj@mh)**2/(1-zj*zj)\n        pair=green22(np_,mp_,nq,mq,L)\n        # ABbar and BAbar have distinct spin phases and remain separate.\n        out[ih,2,3]=.5*common*dot*f_at(np_)*pair.conjugate()\n        out[ih,2,4]=.5*common*dot*f_at(nq)*pair.conjugate()\n        out[ih,3,3]=.5*common*dot*f_at(np_)*pair\n        out[ih,3,4]=.5*common*dot*f_at(nq)*pair\n    return out\n\ndef jacobi_mp(n,a,b,x):\n    if n<0:return mp.mpf(0)\n    p0=mp.mpf(1)\n    if n==0:return p0\n    p1=((a-b)+(a+b+2)*x)/2\n    for k in range(2,n+1):\n        t=2*k+a+b\n        pk=((t-1)*(t*(t-2)*x+a*a-b*b)*p1-2*(k+a-1)*(k+b-1)*t*p0)/(2*k*(k+a+b)*(t-2))\n        p0,p1=p1,pk\n    return p1\n\ndef greens_mp(x,L):\n    X=(1-x)/2;S=Sp=Spp=G=mp.mpf(0)\n    for ell in range(2,L+1):\n        n=ell-2;c=(2*ell+1)/(4*mp.pi)*mp.exp(-mp.mpf(16)*ell*(ell+1)/L**2)\n        S+=c*jacobi_mp(n,4,0,x)\n        Sp+=c*mp.mpf(n+5)/2*jacobi_mp(n-1,5,1,x)\n        Spp+=c*mp.mpf((n+5)*(n+6))/4*jacobi_mp(n-2,6,2,x)\n        G+=c/mp.mpf((ell-1)*ell*(ell+1)*(ell+2))*(1-x*x)*(ell+1)*(ell+2)/4*jacobi_mp(n,2,2,x)\n    return X*X*S,-X*S+X*X*Sp,S/2-2*X*Sp+X*X*Spp,G\n\ndef gauss_mp(n):\n    """Double seeds refined with mp Legendre recurrence; weights also mp."""\n    seeds=leggauss(n)[0];nodes=[];weights=[]\n    for seed in seeds:\n        x=mp.mpf(float(seed))\n        for _ in range(16):\n            a,b=mp.mpf(1),x\n            for k in range(2,n+1): a,b=b,((2*k-1)*x*b-(k-1)*a)/k\n            dp=n*(x*b-a)/(x*x-1);dx=b/dp;x-=dx\n            if abs(dx)<32*mp.eps:break\n        a,b=mp.mpf(1),x\n        for k in range(2,n+1):a,b=b,((2*k-1)*x*b-(k-1)*a)/k\n        dp=n*(x*b-a)/(x*x-1)\n        nodes.append(x);weights.append(2/((1-x*x)*dp*dp))\n    return nodes,weights\n\ndef collinear_mp(dps,L=16,nx=96,nphi=32,shift=\'0.137\'):\n    with mp.workdps(dps):\n        nodes,weights=gauss_mp(nx);rad=[mp.mpc(0) for _ in range(3)];absrad=[mp.mpf(0) for _ in range(3)]\n        p=mp.mpf(1);q=s=mp.mpf(\'.5\');E=p+q\n        common=-1j*(E-s)/(2*mp.pi*mp.sqrt(2)*s)\n        def prod(a,b):return (a[0]*b[0],a[1]*b[0]+a[0]*b[1],a[2]*b[0]+2*a[1]*b[1]+a[0]*b[2])\n        for x,w in zip(nodes,weights):\n            R,Rp,Rpp,G=greens_mp(x,L);B,Bp,Bpp,_=greens_mp(-x,L)\n            h=prod((R,Rp,Rpp),(B,-Bp,Bpp));D=(E-s*x)/mp.sqrt(2)\n            C=(p*q*(1-x*x)/2,-p*q*x,-p*q)\n            A=prod(prod(C,C),(D**-2,mp.sqrt(2)*s/D**3,3*s*s/D**4))\n            def lap(y):return (1-x*x)*y[2]-2*x*y[1]-16*y[0]/(1-x*x)\n            src=[2*lap(prod(C,h)),2*lap(prod(A,h)),2*p*q*h[0]]\n            for j,z in enumerate(src):\n                val=common/2*w*G/D*z;rad[j]+=val;absrad[j]+=abs(val)\n        rows=[]\n        for hout,hu,hv in itertools.product((2,-2),repeat=3):\n            weight=hout-hu+hv\n            # Explicit complex exponential sum, never replacing it with zero.\n            az=mp.fsum(mp.exp(1j*weight*(2*mp.pi*j/nphi+mp.mpf(shift))) for j in range(nphi))*2*mp.pi/nphi\n            blocks=[r*az for r in rad]+[mp.mpc(0),mp.mpc(0)] if hu!=hv else [mp.mpc(0)]*5\n            z=mp.fsum(blocks)\n            scale=2*mp.pi*mp.fsum(absrad) if hu!=hv else mp.mpf(0)\n            rows.append({\'helicities\':[hout,hu,hv],\'axial_weight\':weight,\'blocks\':[[mp.nstr(v.real,dps),mp.nstr(v.imag,dps)] for v in blocks],\n                         \'kernel_abs\':mp.nstr(abs(z),dps),\'relative_to_absolute_integrand\':mp.nstr(abs(z)/scale,dps) if scale else None})\n        return {\'dps\':dps,\'L\':L,\'nx\':nx,\'nphi\':nphi,\'rows\':rows,\'max_kernel_abs\':mp.nstr(max(mp.mpf(r[\'kernel_abs\']) for r in rows),dps),\n                \'radial_prefactors\':[[mp.nstr(r.real,dps),mp.nstr(r.imag,dps)] for r in rad],\n                \'absolute_integrand_scale\':mp.nstr(2*mp.pi*mp.fsum(absrad),dps)}\n\ndef local_mp(dps,L=24,t=\'2\',xi=\'.3\',s=\'.5\'):\n    """Nonzero equal-helicity channel: its two local deltas are exact."""\n    with mp.workdps(dps):\n        t,xi,s=map(mp.mpf,(t,xi,s));p=s*(t+xi)/2;q=s*(t-xi)/2;E=s*t\n        cp=(1+t*xi)/(t+xi);cq=(1-t*xi)/(t-xi)\n        pair=greens_mp(1-2*(t*t-1)/(t*t-xi*xi),L)[0]\n        dot=(E*E-s*s)/2;common=-1j*(E-s)/(2*mp.pi*mp.sqrt(2)*s)\n        vals=[common/2*dot*greens_mp(c,L)[3]/((E-s*c)/mp.sqrt(2))*pair for c in (cp,cq)]\n        return {\'dps\':dps,\'L\':L,\'blocks_im\':[mp.nstr(v.imag,dps) for v in vals], \'total_im\':mp.nstr(mp.fsum(vals).imag,dps)}\n\ndef mixed_mp(dps=50,L=12,nx=48,nphi=64):\n    """Genuinely nonzero mixed-helicity blocks, all arithmetic in mpmath."""\n    with mp.workdps(dps):\n        t=mp.mpf(2);xi=mp.mpf(\'.3\');s=mp.mpf(\'.5\');p=s*(t+xi)/2;q=s*(t-xi)/2;E=s*t\n        pz=s*(1+t*xi)/2;px=s/2*mp.sqrt((t*t-1)*(1-xi*xi))\n        np_=[px/p,mp.mpf(0),pz/p];nq=[-px/q,mp.mpf(0),(s-pz)/q]\n        mdp=[np_[2]/mp.sqrt(2),1j/mp.sqrt(2),-np_[0]/mp.sqrt(2)]\n        mdq=[-nq[2]/mp.sqrt(2),-1j/mp.sqrt(2),nq[0]/mp.sqrt(2)]\n        dot=lambda a,b:mp.fsum(u*v for u,v in zip(a,b))\n        coeffs=[(ell,(2*ell+1)/(4*mp.pi)*mp.exp(-mp.mpf(16)*ell*(ell+1)/L**2)) for ell in range(2,L+1)]\n        def gj(n,m,nj,mj):\n            z=dot(n,nj);X=(1-z)/2\n            A=-dot(m,nj)/mp.sqrt(2);B=-dot(n,mj)/mp.sqrt(2);C=-dot(m,mj)\n            # |(AB-XC)^2|=X^2: cancel that factor analytically before division.\n            return (A*B-X*C)**2*mp.fsum(c*jacobi_mp(ell-2,4,0,z) for ell,c in coeffs)\n        nodes,weights=gauss_mp(nx);out=[[mp.mpc(0) for _ in range(3)] for _ in range(2)]\n        common=-1j*(E-s)/(2*mp.pi*mp.sqrt(2)*s);fourdot=p*q-dot([px,0,pz],[-px,0,s-pz])\n        trig=[(mp.cos(2*mp.pi*j/nphi+mp.mpf(\'.173\')),mp.sin(2*mp.pi*j/nphi+mp.mpf(\'.173\'))) for j in range(nphi)]\n        for x,w in zip(nodes,weights):\n            R=Rp=Rpp=mp.mpf(0)\n            for ell,c in coeffs:\n                nn=ell-2;c=c/mp.mpf((ell-1)*ell*(ell+1)*(ell+2))*(ell+1)*(ell+2)/4\n                J=jacobi_mp(nn,2,2,x);Jp=mp.mpf(nn+5)/2*jacobi_mp(nn-1,3,3,x);Jpp=mp.mpf((nn+5)*(nn+6))/4*jacobi_mp(nn-2,4,4,x)\n                R+=c*(1-x*x)*J;Rp+=c*(-2*x*J+(1-x*x)*Jp);Rpp+=c*(-2*J-4*x*Jp+(1-x*x)*Jpp)\n            D=(E-s*x)/mp.sqrt(2);fr=R/D;fp=Rp/D+R*s/mp.sqrt(2)/D**2;fpp=Rpp/D+mp.sqrt(2)*s*Rp/D**2+s*s*R/D**3\n            lapfr=(1-x*x)*fpp-2*x*fp-4*fr/(1-x*x);st=mp.sqrt(1-x*x)\n            for co,si in trig:\n                n=[st*co,st*si,x];m=[(x*co-1j*si)/mp.sqrt(2),(x*si+1j*co)/mp.sqrt(2),-st/mp.sqrt(2)]\n                h=gj(n,m,np_,mdp)*mp.conj(gj(n,m,nq,mdq));phase=(co+1j*si)**2\n                C=(p-dot(n,[px,0,pz]))*(q-dot(n,[-px,0,s-pz]))/2;A=(C/D)**2\n                for j,hh in enumerate((h,mp.conj(h))):\n                    for b,z in enumerate((2*lapfr*C,2*lapfr*A,fr*fourdot)):\n                        out[j][b]+=common/2*w*2*mp.pi/nphi*phase*z*hh\n        return {\'dps\':dps,\'L\':L,\'nx\':nx,\'nphi\':nphi,\'blocks\':[[[mp.nstr(z.real,dps),mp.nstr(z.imag,dps)] for z in row] for row in out],\n                \'totals_im\':[mp.nstr(mp.fsum(row).imag,dps) for row in out]}\n\ndef rotation_matrix():\n    a=np.array([.3,-.4,.5]);a/=np.linalg.norm(a);angle=.71\n    C=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])\n    return np.eye(3)*np.cos(angle)+(1-np.cos(angle))*np.outer(a,a)+np.sin(angle)*C\n\ndef physical_rotation_phases(pv,qv,R):\n    out=[]\n    for v in (pv+qv,pv,qv):\n        old=R@frame(v)[1];new=frame(R@v)[1];z=new@old.conj();out.append(z/abs(z))\n    return np.array([[out[0]**hout*out[1]**(-hu)*out[2]**(-hv) for hu,hv in HELS] for hout in (2,-2)])\n\ndef expanded_algebra():\n    """Separate F/W, normal polynomial vs direct occupation action; no cutoff."""\n    sys.path.insert(0,str(ROOT.parent/\'recalculo_bondi_corregido\'))\n    from algebra_bosonica import add,scale,mul,comm,mono\n    from recalcular import adj,ev,audit\n    result=[]\n    for seed in (17421,821,9001):\n        audit(seed)\n        rng=np.random.default_rng(seed);w=np.array([.5,.5,1.]);n=3\n        K=rng.normal(size=(n,n,n))+1j*rng.normal(size=(n,n,n));K=(K+K.swapaxes(1,2))/2\n        A={};H={}\n        for p in range(n):H=add(H,scale(mono(n,(p,),(p,)),2*w[p]))\n        for p,u,v in itertools.product(range(n),repeat=3):A=add(A,scale(mono(n,(p,),(u,v)),K[p,u,v]))\n        T=scale(add(A,scale(adj(A),-1)),-2j)\n        W=mul(T,T);F=mul(mul(T,H),T);D=scale(comm(comm(H,T),T),-.5)\n        for occ in ((1,1,0),(2,0,0),(0,0,2),(2,1,0),(1,1,1),(3,2,0)):\n            out={}\n            for (cre,ann),coef in T.items():\n                ns=list(occ);z=coef\n                for mode in range(n):\n                    for _ in range(ann[mode]):\n                        if ns[mode]==0:z=0;break\n                        z*=np.sqrt(ns[mode]/2);ns[mode]-=1\n                    if z==0:break\n                if not z:continue\n                for mode in range(n):\n                    for _ in range(cre[mode]):z*=np.sqrt((ns[mode]+1)/2);ns[mode]+=1\n                out[tuple(ns)]=out.get(tuple(ns),0)+z\n            fw=sum(abs(z)**2 for z in out.values())\n            ff=sum(float(w@state)*abs(z)**2 for state,z in out.items())\n            ei=float(w@occ);pw=ev(W,occ);pf=ev(F,occ);pd=ev(D,occ)\n            errors={\'W_direct_vs_polynomial\':float(abs(fw-pw)), \'F_direct_vs_polynomial\':float(abs(ff-pf)),\n                    \'D_direct_vs_commutator\':float(abs(ff-ei*fw-pd))}\n            relative=max(errors.values())/max(fw,ff,abs(ff-ei*fw),1.)\n            assert relative<1e-12,(occ,errors,relative)\n            result.append({\'seed\':seed,\'occupation\':occ,\'Ei\':ei,\'initial_unnormalized_norm\':math.prod(math.factorial(k)/2**k for k in occ),\n                           \'normalized_W\':fw,\'normalized_F\':ff,\'normalized_D\':ff-ei*fw,\'errors\':errors,\'max_relative_error\':relative})\n    return result\n\ndef precision_checks(data):\n    with mp.workdps(110):\n        a,b,c=data[\'nonzero_mixed_precision\']\n        precision=max(abs(mp.mpf(u)-mp.mpf(v)) for u,v in zip(a[\'totals_im\'],b[\'totals_im\']))\n        grid=max(abs(mp.mpf(u)-mp.mpf(v)) for u,v in zip(b[\'totals_im\'],c[\'totals_im\']))\n        local=abs(mp.mpf(data[\'nonzero_local_precision\'][0][\'total_im\'])-mp.mpf(data[\'nonzero_local_precision\'][1][\'total_im\']))\n        radial=max(abs(mp.mpf(u[1])-mp.mpf(v[1])) for u,v in zip(data[\'radial_quadrature\'][0][\'radial_prefactors\'],data[\'radial_quadrature\'][-1][\'radial_prefactors\']))\n        assert precision<mp.mpf(\'1e-38\') and grid<mp.mpf(\'1e-40\') and local<mp.mpf(\'1e-28\') and radial<mp.mpf(\'1e-50\')\n        data[\'precision_comparisons\']={\'mixed_40_vs_70_digits_max_difference\':mp.nstr(precision,30),\n           \'mixed_grid_48x64_vs_72x96_max_difference\':mp.nstr(grid,30),\n           \'local_30_vs_60_digits_difference\':mp.nstr(local,30),\n           \'collinear_radial_n48_vs_n120_max_difference\':mp.nstr(radial,30)}\n    float_mp=max(abs(float(v)-data[\'nonzero_grid\'][0][\'total\'][0][j][1]) for j,v in enumerate(b[\'totals_im\']))\n    assert float_mp<1e-17\n    data[\'precision_comparisons\'][\'mixed_mp_vs_float64_max_difference\']=float_mp\n\ndef main():\n    t,xi,s=2.,.3,.5\n    pv=np.array([s/2*np.sqrt((t*t-1)*(1-xi*xi)),0.,s/2*(1+t*xi)])\n    qv=np.array([-pv[0],0.,s-pv[2]])\n    data={\'scope\':\'five geometric aa source blocks, common finite heat projection; not full normalized Hermitian T1\',\n          \'regulator\':\'exp(-16 ell(ell+1)/L^2) on ALL nonlocal Greens including external G20; local angular deltas exact\',\n          \'configuration\':{\'p\':pv.tolist(),\'q\':qv.tolist(),\'output\':(pv+qv).tolist(),\'input_energy\':float(np.linalg.norm(pv)+np.linalg.norm(qv)),\'output_energy\':s,\'energy_conservation_imposed\':False},\n          \'blocks\':BLOCKS,\'helicity_pairs\':HELS}\n    data[\'collinear_precision\']=[]\n    for dps in (30,60,100):\n        result=collinear_mp(dps);data[\'collinear_precision\'].append(result)\n        print(\'precision\',dps,result[\'max_kernel_abs\'],flush=True)\n    data[\'radial_quadrature\']=[collinear_mp(60,nx=n) for n in (48,72,120)]\n    data[\'nonzero_local_precision\']=[local_mp(dps) for dps in (30,60,100)]\n    data[\'nonzero_mixed_precision\']=[mixed_mp(40),mixed_mp(70),mixed_mp(50,nx=72,nphi=96)]\n    grids=[]\n    for L in (12,24,48):\n        a=vector_blocks(pv,qv,L);b=vector_blocks(pv,qv,L,nx=2*(6*L+24),nphi=2*(8*L+48),shift=.417)\n        grids.append({\'L\':L,\'blocks\':encode(a),\'total\':encode(a.sum(-1)),\'doubled_grid_max_abs_difference\':float(np.max(abs(a-b))),\n                      \'doubled_grid_max_relative_difference\':float(np.max(abs(a-b))/np.max(abs(b)))})\n        print(\'nonzero\',L,grids[-1][\'total\'],\'grid error\',grids[-1][\'doubled_grid_max_abs_difference\'],flush=True)\n    data[\'nonzero_grid\']=grids\n    L=24;base=vector_blocks(pv,qv,L)\n    spectral=[]\n    for cutoff in (32,48,72):\n        z=vector_blocks(pv,qv,L,route=\'source\',ellmax=cutoff,nx=192,nphi=256)\n        spectral.append({\'ellmax\':cutoff,\'blocks\':encode(z),\'difference_from_external_route\':float(np.max(abs(z-base)))})\n    data[\'independent_laplacian_route\']=spectral\n    swapped=vector_blocks(qv,pv,L)\n    data[\'bose_max_block_error\']=float(np.max(abs(base-swapped[:,[1,0,2,3]][:,:,[0,1,2,4,3]])))\n    data[\'parity_max_block_error\']=float(np.max(abs(base[1]+base[0,[1,0,3,2]].conj())))\n    angles=np.array([.31,-.23,.47]);changed=vector_blocks(pv,qv,L,basis=angles)\n    prediction=np.array([[np.exp(1j*(hout*angles[0]-hu*angles[1]-hv*angles[2])) for hu,hv in HELS] for hout in (2,-2)])\n    data[\'basis_change_max_block_error\']=float(np.max(abs(changed-base*prediction[:,:,None])))\n    R=rotation_matrix();rotated=vector_blocks(R@pv,R@qv,L,shift=.29)\n    prediction=physical_rotation_phases(pv,qv,R)\n    data[\'spatial_rotation_max_block_error\']=float(np.max(abs(rotated-base*prediction[:,:,None])))\n    # Same-support match against earlier source-derivative collinear evaluator.\n    aligned=vector_blocks([0,0,1],[0,0,-.5],L)\n    old=previous_run(L)\n    data[\'collinear_max_residual_external_route\']=float(np.max(abs(aligned.sum(-1))))\n    data[\'collinear_max_residual_previous_route\']=old[\'max_kernel_abs\']\n    data[\'local_mp_vs_float64_error\']=float(abs(base[0,2].sum().imag-float(data[\'nonzero_local_precision\'][1][\'total_im\'])))\n    data[\'sensitivity_omega_times_seven\']={\'baseline\':encode(base.sum(-1)), \'modified\':encode((base*np.array([7,7,1,1,1])).sum(-1)),\n        \'max_abs_change\':float(np.max(abs((base*np.array([7,7,1,1,1])).sum(-1)-base.sum(-1))))}\n    assert data[\'bose_max_block_error\']<1e-12\n    assert data[\'parity_max_block_error\']<1e-12\n    assert data[\'basis_change_max_block_error\']<1e-12\n    assert data[\'spatial_rotation_max_block_error\']<1e-10\n    assert spectral[-1][\'difference_from_external_route\']<1e-10\n    assert data[\'local_mp_vs_float64_error\']<1e-14\n    assert max(r[\'doubled_grid_max_abs_difference\'] for r in grids)<1e-10\n    data[\'source_sha256\']={str(p.relative_to(ROOT.parents[1])):hashlib.sha256(p.read_bytes()).hexdigest() for p in [Path(__file__),PREVIOUS/\'calcular_deltaE.py\',ROOT.parents[1]/\'upload/Quantum_scattering_I_revised(3).pdf\'] if p.exists()}\n    data[\'expanded_algebra\']=expanded_algebra()\n    precision_checks(data)\n    data[\'open_checks\']=[\'Full oscillator/mode prefactors and BCH map to Hermitian T1 away from collinearity\',\n        \'Physical common finite-volume connected W,F,D benchmark (generic algebra expanded separately)\', \'Regulator-removal and packet limits\',\n        \'Full connected T2/T3 generators and scattering weights\']\n    (ROOT/\'resultados_control.json\').write_text(json.dumps(data,indent=2)+\'\\n\')\n    print(json.dumps({k:v for k,v in data.items() if \'error\' in k or \'residual\' in k},indent=2),flush=True)\n\nif __name__==\'__main__\':main()\n', 'canal_23/control_fisico_WFD/calcular_WFD.py': '"""Connected W,F,D with BCH mode factors and ONE momentum-cell regulator.\n\nScope: complete selected CoM connected diagonal epsilon^2 coefficient, with\nexact zero mode excluded and finite common angular heat projection. Nonzero\nnoncollinear checks isolate the merger topology, not the full non-CoM result.\nG=1 and frequencies in the chosen reference-energy units.\nDependencies: numpy, scipy, mpmath; prior angular scripts bundled alongside.\n"""\nimport sys,json,itertools,math,hashlib\nfrom pathlib import Path\nimport mpmath as mp\nimport numpy as np\n\nROOT=Path(__file__).resolve().parent\nsys.path.insert(0,str(ROOT.parent/\'control_nucleo_etapa1\'))\nfrom control_nucleo import collinear_mp,vector_blocks\n\ndef nu_bch(w,G=1):\n    """BCH Eq.(87), measure dPi=d3k/[(2pi)^3 2w]."""\n    return 8*mp.pi**2*mp.sqrt(4*mp.pi*G)*mp.mpf(w)**(-mp.mpf(3)/2)\n\ndef nu0(w,G=1):\n    """Same shear and same a, with BCH dmu0=d3k/(2w)."""\n    return nu_bch(w,G)/(2*mp.pi)**3\n\ndef mode_factor(parent,u,v,G=1):\n    # The bare extraction coefficient ALREADY contains its outgoing kinematic\n    # factor. Do not multiply it by another 2w. In source-vertex notation the\n    # same result is N2*V2/(2pi)^3, with V2=geo/(2w).\n    return nu0(u,G)*nu0(v,G)/nu0(parent,G)\n\ndef symmetric_tensor(parent,u,v,geometric,G=1):\n    return mode_factor(parent,u,v,G)*geometric\n\ndef mono(n,cre=(),ann=()):\n    return {(tuple(cre.count(i) for i in range(n)),tuple(ann.count(i) for i in range(n))):mp.mpc(1)}\n\ndef add(*polys):\n    out={}\n    for p in polys:\n        for key,v in p.items():out[key]=out.get(key,mp.mpc(0))+v\n    return {k:v for k,v in out.items() if v!=0}\n\ndef scale(p,z):return {k:z*v for k,v in p.items()}\ndef adj(p):return {(s,r):mp.conj(v) for (r,s),v in p.items()}\n\ndef mul(p,q):\n    """Normal-polynomial product, canonical c CCR=1, no Fock truncation."""\n    out={}\n    for (r,s),a in p.items():\n      for (u,v),b in q.items():\n       for k in itertools.product(*(range(min(si,ui)+1) for si,ui in zip(s,u))):\n        coef=a*b\n        for si,ui,ki in zip(s,u,k):coef*=math.comb(si,ki)*math.comb(ui,ki)*math.factorial(ki)\n        key=(tuple(ri+ui-ki for ri,ui,ki in zip(r,u,k)),tuple(si+vi-ki for si,vi,ki in zip(s,v,k)))\n        out[key]=out.get(key,mp.mpc(0))+coef\n    return add(out)\n\ndef comm(p,q):return add(mul(p,q),scale(mul(q,p),-1))\n\ndef expectation(p,occ,degree=None):\n    z=mp.mpc(0)\n    for (r,s),v in p.items():\n        if degree is not None and sum(r)+sum(s)!=degree:continue\n        if r!=s or any(si>ni for si,ni in zip(s,occ)):continue\n        for si,ni in zip(s,occ):v*=math.factorial(ni)//math.factorial(ni-si)\n        z+=v\n    return z\n\ndef action(p,occ):\n    out={}\n    for (cre,ann),coef in p.items():\n        ns=list(occ);z=coef\n        for mode in range(len(ns)):\n            for _ in range(ann[mode]):\n                if ns[mode]==0:z=0;break\n                z*=mp.sqrt(ns[mode]);ns[mode]-=1\n            if z==0:break\n        if not z:continue\n        for mode in range(len(ns)):\n            for _ in range(cre[mode]):z*=mp.sqrt(ns[mode]+1);ns[mode]+=1\n        out[tuple(ns)]=out.get(tuple(ns),mp.mpc(0))+z\n    return out\n\ndef moments(T,w,occ):\n    psi=action(T,occ)\n    W=mp.fsum(abs(z)**2 for z in psi.values())\n    F=mp.fsum(mp.fsum(a*b for a,b in zip(w,state))*abs(z)**2 for state,z in psi.items())\n    return W,F\n\ndef direct_connected(T,w,i,j):\n    n=len(w);one=[0]*n;two=[0]*n;one[i]=1;two[j]=1\n    W1,F1=moments(T,w,one);W2,F2=moments(T,w,two);occ=[a+b for a,b in zip(one,two)]\n    W,F=moments(T,w,occ)\n    # Subtract one-body terms with the spectator energy included in F.\n    wc=W-W1-W2;fc=F-(F1+w[j]*W1)-(F2+w[i]*W2)\n    return wc,fc,fc-(w[i]+w[j])*wc,(W,F,W1,F1,W2,F2)\n\ndef generator(w,vertices,cell):\n    """Unordered distinct daughters: Bose factor two explicit in gamma.\n\n    For one ORDERED slot Gamma=-i sqrt(v) kappa/(4 sqrt(wp wu wv)).\n    Every vertex here has distinct daughter momenta, hence two equal slots.\n    """\n    n=len(w);A={};records=[]\n    for p,u,v,kappa in vertices:\n        assert u!=v\n        gamma=-1j*mp.sqrt(cell)*kappa/(2*mp.sqrt(w[p]*w[u]*w[v]))\n        A=add(A,scale(mono(n,(p,),(u,v)),gamma))\n        records.append({\'indices\':[p,u,v],\'gamma_re_im\':[mp.nstr(gamma.real,30),mp.nstr(gamma.imag,30)]})\n    T=add(A,adj(A));H={}\n    for j,ww in enumerate(w):H=add(H,scale(mono(n,(j,),(j,)),ww))\n    return T,H,records\n\ndef polynomial_errors(T,H,w,occupation,wc,fc,dc):\n    # Quartic selection applied to EACH product before subtraction.\n    W=mul(T,T);F=mul(mul(T,H),T)\n    w4=expectation(W,occupation,4);naive_f4=expectation(F,occupation,4)\n    occupied=[j for j,k in enumerate(occupation) if k]\n    assert len(occupied)==2 and all(occupation[j]==1 for j in occupied)\n    i,j=occupied;one=[0]*len(w);two=one.copy();one[i]=1;two[j]=1\n    # In T H T a quartic monomial can still have a DISCONNECTED H on the\n    # spectator. Degree alone does not implement external connectedness.\n    disconnected_H=w[j]*expectation(W,one,2)+w[i]*expectation(W,two,2)\n    f4=naive_f4-disconnected_H\n    double=scale(comm(comm(H,T),T),-mp.mpf(\'.5\'))\n    d4=expectation(double,occupation,4)\n    err=max(abs(w4-wc),abs(f4-fc),abs(d4-dc))\n    denom=max(abs(wc),abs(fc),abs(dc),mp.mpf(\'1e-10000\'))\n    return err,err/denom,{\'W4\':w4,\'F4\':f4,\'F4_before_H_spectator_removal\':naive_f4,\'disconnected_H\':disconnected_H,\'D4_double_commutator\':d4}\n\ndef output_record(wc,fc,dc,wi,wj,cell,digits=40):\n    norm=wi*wj/cell**2;norm_g=cell**-2\n    fmt=lambda z:mp.nstr(mp.re(z),digits)\n    record={\'cell_d3k\':fmt(cell),\'delta3_zero\':fmt(1/cell),\'spatial_volume\':fmt((2*mp.pi)**3/cell),\n       \'Ni_a\':fmt(norm),\'Ni_Gasiorowicz\':fmt(norm_g),\n       \'normalized\':{\'W\':fmt(wc),\'F\':fmt(fc),\'D\':fmt(dc)},\n       \'raw_a\':{\'W\':fmt(norm*wc),\'F\':fmt(norm*fc),\'D\':fmt(norm*dc)},\n       \'raw_Gasiorowicz\':{\'W\':fmt(norm_g*wc),\'F\':fmt(norm_g*fc),\'D\':fmt(norm_g*dc)},\n       \'coefficient_after_one_delta_a\':{\'W\':fmt(norm*wc*cell),\'F\':fmt(norm*fc*cell),\'D\':fmt(norm*dc*cell)},\n       \'coefficient_after_one_delta_Gasiorowicz\':{\'W\':fmt(wc/cell),\'F\':fmt(fc/cell),\'D\':fmt(dc/cell)}}\n    for value,raw in ((wc,norm*wc),(fc,norm*fc),(dc,norm*dc)):\n        assert abs(raw/norm-value)<128*mp.eps*max(abs(value),mp.mpf(\'1e-10000\'))\n    return record\n\ndef ccr_check(T,H,w,cell,vertices):\n    n=len(w);target={}\n    # Independently build both aa and ca outgoing coefficients from complete\n    # distributions K, L=-2K* and the two daughter Bose slots.\n    for p,u,v,kappa in vertices:\n        g=mp.sqrt(cell)*kappa/(2*mp.sqrt(w[p]*w[u]*w[v]))\n        target[p]=add(target.get(p,{}),scale(mono(n,(),(u,v)),g))\n        target[u]=add(target.get(u,{}),scale(mono(n,(v,),(p,)),-mp.conj(g)))\n        target[v]=add(target.get(v,{}),scale(mono(n,(u,),(p,)),-mp.conj(g)))\n    error=scale_energy=mp.mpf(0)\n    for j in range(n):\n        c=mono(n,(),(j,));a=scale(c,mp.sqrt(w[j]/cell))\n        out=scale(comm(a,T),1j)\n        expected=scale(target.get(j,{}),mp.sqrt(w[j]/cell))\n        error=max(error,max(map(abs,add(out,scale(expected,-1)).values()),default=mp.mpf(0)))\n        eig=add(comm(H,a),scale(a,w[j]))\n        scale_energy=max(scale_energy,max(map(abs,eig.values()),default=mp.mpf(0)))\n    assert scale_energy<128*mp.eps*max(w)\n    return error\n\ndef com_benchmark(dps=60,L=16,cells=(\'0.125\',\'0.015625\',\'0.001953125\'),G=1):\n    first=collinear_mp(dps,L=L,shift=\'.137\');second=collinear_mp(dps,L=L,shift=\'.531\')\n    result=[]\n    with mp.workdps(dps+30):\n        w=[mp.mpf(\'.5\')]*4+[mp.mpf(1)]*4;vertices=[];lookup=[]\n        for direction,run in enumerate((first,second)):\n            lut={}\n            for row in run[\'rows\']:\n                z=mp.fsum(mp.mpc(*block) for block in row[\'blocks\'])\n                lut[tuple(row[\'helicities\'])]=symmetric_tensor(\'.5\',\'1\',\'.5\',z,G)\n            lookup.append(lut)\n            for hp,hr,hv in itertools.product((2,-2),repeat=3):\n                p=2*direction+int(hp<0);u=4+2*direction+int(hr<0);v=2*(1-direction)+int(hv<0)\n                vertices.append((p,u,v,lut[(hp,hr,hv)]))\n        for cell0 in cells:\n            cell=mp.mpf(cell0);T,H,_=generator(w,vertices,cell)\n            ce=ccr_check(T,H,w,cell,vertices)\n            for h1,h2 in itertools.product((2,-2),repeat=2):\n                i=int(h1<0);j=2+int(h2<0);occ=[0]*8;occ[i]=occ[j]=1\n                wc,fc,dc,full=direct_connected(T,w,i,j)\n                e,relative,poly=polynomial_errors(T,H,w,occ,wc,fc,dc)\n                # Spatial deltas leave only two exchange supports r=+/-z.\n                coeff=mp.fsum(abs(lookup[0][h1,hr,h2])**2+abs(lookup[1][h2,hr,h1])**2 for hr in (2,-2))\n                closedW=cell*coeff;closedF=2*closedW;closedD=closedW\n                eqerr=max(abs(wc-closedW),abs(fc-closedF),abs(dc-closedD))\n                assert relative<mp.mpf(\'1e-\'+str(dps+15))\n                assert eqerr<mp.mpf(\'1e-\'+str(dps+15))*max(abs(closedF),mp.mpf(\'1e-10000\'))\n                r=output_record(wc,fc,dc,w[i],w[j],cell,dps)\n                r.update({\'incoming_helicities\':[h1,h2],\'source_dps\':dps,\'L\':L,\n                    \'connected_topologies\':[\'exchange +z\',\'exchange -z\'],\'zero_mode_excluded\':[\'merger p=0\',\'exchange r=0 in both cross pairings\'],\n                    \'direct_vs_quartic_relative_error\':mp.nstr(relative,20),\'direct_vs_resolved_delta_absolute_error\':mp.nstr(eqerr,20),\n                    \'outgoing_map_absolute_error\':mp.nstr(ce,20),\n                    \'quartic_F_before_H_spectator_removal\':mp.nstr(mp.re(poly[\'F4_before_H_spectator_removal\']),dps),\n                    \'disconnected_H_removed_from_quartic_F\':mp.nstr(mp.re(poly[\'disconnected_H\']),dps),\n                    \'full_retained_stencil_normalized_W\':mp.nstr(full[0],dps),\'full_retained_stencil_normalized_F\':mp.nstr(full[1],dps)})\n                result.append(r)\n        factor=mp.nstr(mode_factor(\'.5\',\'1\',\'.5\',G),30)\n    return {\'source_first\':first,\'source_second\':second,\'mode_factor\':factor,\'rows\':result}\n\ndef nonzero_merger(G=1):\n    # Complete geometric source evaluated directly for each output helicity.\n    s=.5;t=2.;xi=.3;px=s/2*np.sqrt((t*t-1)*(1-xi*xi));pz=s/2*(1+t*xi)\n    pv=np.array([px,0.,pz]);qv=np.array([-px,0.,s-pz])\n    blocks=vector_blocks(pv,qv,24);geo=blocks.sum(-1)\n    vertices=[]\n    with mp.workdps(90):\n        w=[mp.mpf(\'.5\')]*2+[mp.mpf(\'.575\')]*2+[mp.mpf(\'.425\')]*2\n        hels=[(-2,2),(2,-2),(2,2),(-2,-2)]\n        for h,hp in enumerate((2,-2)):\n            for j,(hu,hv) in enumerate(hels):\n                z=mp.mpc(float(geo[h,j].real),float(geo[h,j].imag))\n                vertices.append((h,2+int(hu<0),4+int(hv<0),symmetric_tensor(w[h],w[2],w[4],z,G)))\n        records=[]\n        # Compatible anisotropic momentum lattice, refined with fixed external k.\n        px_mp=mp.sqrt(mp.mpf(\'2.73\'))/4\n        for refinement in (1,2,4):\n            cell=px_mp*mp.mpf(\'.01\')/refinement**3\n            T,H,_=generator(w,vertices,cell);ce=ccr_check(T,H,w,cell,vertices)\n            for hu,hv in itertools.product((2,-2),repeat=2):\n                i=2+int(hu<0);j=4+int(hv<0);occ=[0]*6;occ[i]=occ[j]=1\n                wc,fc,dc,_=direct_connected(T,w,i,j)\n                e,rel,_=polynomial_errors(T,H,w,occ,wc,fc,dc)\n                coeff=mp.fsum(abs(k)**2/(4*w[p]*w[u]*w[v]) for p,u,v,k in vertices if u==i and v==j)\n                assert abs(wc-cell*coeff)<mp.mpf(\'1e-80\')*abs(wc)\n                assert abs(fc-mp.mpf(\'.5\')*wc)<mp.mpf(\'1e-80\')*abs(wc)\n                assert abs(dc+mp.mpf(\'.5\')*wc)<mp.mpf(\'1e-80\')*abs(wc)\n                assert rel<mp.mpf(\'1e-80\')\n                r=output_record(wc,fc,dc,w[i],w[j],cell)\n                r.update({\'incoming_helicities\':[hu,hv],\'refinement\':refinement,\'L\':24,\n                    \'lattice_spacings\':[mp.nstr(px_mp/refinement,30),mp.nstr(mp.mpf(\'.1\')/refinement,30),mp.nstr(mp.mpf(\'.1\')/refinement,30)],\n                    \'direct_vs_quartic_relative_error\':mp.nstr(rel,20),\'outgoing_map_absolute_error\':mp.nstr(ce,20)})\n                records.append(r)\n        return {\'scope\':\'NONZERO MERGER TOPOLOGY ONLY; not total non-CoM connected W,F,D\',\n            \'momenta\':{\'p\':pv.tolist(),\'q\':qv.tolist(),\'parent\':[0,0,.5]},\n            \'Ei\':\'1\',\'intermediate_energy\':\'.5\',\'mode_factor\':mp.nstr(mode_factor(\'.5\',\'.575\',\'.425\',G),40),\n            \'rows\':records}\n\ndef volume_checks(result):\n    """One-delta coefficient invariant; normalized sharp-state moments scale v."""\n    with mp.workdps(140):\n        errors=[]\n        by_h={}\n        for r in result[\'rows\']:by_h.setdefault(tuple(r[\'incoming_helicities\']),[]).append(r)\n        for helicities,rows in by_h.items():\n            ref=rows[0]\n            for r in rows[1:]:\n                for key in (\'W\',\'F\',\'D\'):\n                    a=mp.mpf(r[\'normalized\'][key])/mp.mpf(r[\'cell_d3k\'])\n                    b=mp.mpf(ref[\'normalized\'][key])/mp.mpf(ref[\'cell_d3k\'])\n                    rel=abs(a-b)/max(abs(a),abs(b),mp.mpf(\'1e-10000\'))\n                    assert rel<mp.mpf(\'1e-25\')\n                    errors.append(rel)\n        return mp.nstr(max(errors,default=mp.mpf(0)),20)\n\ndef normalization_audit():\n    """Recover the same canonical vertex from THREE explicit dictionaries."""\n    with mp.workdps(100):\n        out=[]\n        for wp,wu,wv in [(\'.5\',\'1\',\'.5\'),(\'.5\',\'.575\',\'.425\')]:\n          p,u,v=map(mp.mpf,(wp,wu,wv))\n          for cell0 in (\'.125\',\'.015625\',\'.001953125\'):\n            cell=mp.mpf(cell0);kappa=mp.mpc(\'.37\',\'-.19\')\n            # One ordered daughter slot, before the distinct-daughter factor 2.\n            g_can=-1j*mp.sqrt(cell)*kappa/(4*mp.sqrt(p*u*v))\n            g_mu=-2j*(cell/(2*p))*(cell/(2*u))*(cell/(2*v))*(1/cell)*kappa*mp.sqrt(p*u*v/cell**3)\n            beta=mp.sqrt(2*(2*mp.pi)**3)\n            kappa_cov=(2*mp.pi)**3/beta*kappa\n            mpi=lambda w:cell/((2*mp.pi)**3*2*w)\n            af=lambda w:mp.sqrt(2*w*(2*mp.pi)**3/cell)\n            g_cov=-1j*mpi(p)*mpi(u)*mpi(v)*(2*mp.pi)**3/cell*kappa_cov*af(p)*af(u)*af(v)\n            err=max(abs(g_mu-g_can),abs(g_cov-g_can))/abs(g_can)\n            assert err<mp.mpf(\'1e-95\')\n            geom=mp.mpc(\'.07\',\'-.13\')\n            f0=mode_factor(p,u,v)\n            fpi=nu_bch(u)*nu_bch(v)/nu_bch(p)/(2*mp.pi)**3\n            mferr=abs(f0-fpi)/abs(f0)\n            assert mferr<mp.mpf(\'1e-95\')\n            ca=mono(2,(0,),());cb=mono(2,(1,),())\n            ket_a=action(mul(scale(ca,mp.sqrt(u/cell)),scale(cb,mp.sqrt(v/cell))),(0,0))\n            ket_g=action(mul(scale(ca,1/mp.sqrt(cell)),scale(cb,1/mp.sqrt(cell))),(0,0))\n            norm_a=mp.fsum(abs(z)**2 for z in ket_a.values());norm_g=mp.fsum(abs(z)**2 for z in ket_g.values())\n            norm_error=max(abs(norm_a/(u*v/cell**2)-1),abs(norm_g/(1/cell**2)-1))\n            assert norm_error<mp.mpf(\'1e-95\')\n            out.append({\'frequencies\':[wp,wu,wv],\'cell\':cell0,\'canonical_vs_mu0_vs_covariant_relative_error\':mp.nstr(err,25),\n                        \'mode_measure_conversion_relative_error\':mp.nstr(mferr,25),\'initial_norm_direct_creation_relative_error\':mp.nstr(norm_error,25)})\n        # The gravitational factor is restored once: kappa ∝ sqrt(G).\n        gravity=abs(mode_factor(\'.5\',\'.575\',\'.425\',G=4)/mode_factor(\'.5\',\'.575\',\'.425\',G=1)-2)\n        assert gravity<mp.mpf(\'1e-95\')\n        return {\'three_dictionary_checks\':out,\'G4_vs_G1_kernel_ratio_error\':mp.nstr(gravity,25)}\n\ndef main():\n    data={\'G\':1,\'hbar_c\':1,\'observable\':\'connected diagonal epsilon^2 coefficient in CoM; NOT full expectation or exclusive scattering probability\',\n          \'BCH_mode_weight\':\'nu(w)=8 pi^2 sqrt(4 pi G) w^(-3/2), Eq.(87)\',\n          \'measure_conversion\':\'dPi=dmu0/(2pi)^3; nu0=nu/(2pi)^3; kappa_aa=(nu0(u)nu0(v)/nu0(p))*kappa_geom\',\n          \'generator\':\'T1=-2i int dmu_p dmu_u dmu_v delta3(p-u-v) kappa_aa a†_p a_u a_v + H.c.\',\n          \'BCH_relation\':\'L(u,v|p)=-2 K(p;u,v)*; this is the adopted BCH reconstruction, not a new independent evaluation of the NSF difference branch\',\n          \'volume_dictionary\':\'v=d3k cell; delta3(0)=1/v; a_j=sqrt(w_j/v)c_j; dmu_j=v/(2w_j); physical box V=(2pi)^3/v\',\n          \'Gasiorowicz_states\':\'b=a/sqrt(w); [b,b†]=delta3; |i_G>=b†1 b†2|0>; Ni_G=1/v^2 for distinct modes\',\n          \'connected_selection\':\'quartic normal sector in each direct product before subtraction; independent action subtracts one-body contributions including spectator energy\',\n          \'com\':[]}\n    for dps in (30,60,100):\n        r=com_benchmark(dps);data[\'com\'].append(r)\n        print(\'CoM\',dps,\'max normalized D residual\',max(float(x[\'normalized\'][\'D\']) for x in r[\'rows\']),flush=True)\n    data[\'nonzero_merger\']=nonzero_merger()\n    data[\'normalization_audit\']=normalization_audit()\n    data[\'volume_scaling_errors\']={\'com\':[volume_checks(r) for r in data[\'com\']], \'nonzero_merger\':volume_checks(data[\'nonzero_merger\'])}\n    data[\'analytic_result_at_each_finite_filter\']={\'Wconn\':0,\'Fconn\':0,\'Dconn\':0,\'DeltaEconn_epsilon2_coefficient\':0}\n    data[\'limits_not_taken\']=[\'angular regulator removal\',\'wave-packet to sharp-state limit\',\'full expectation including spectators\']\n    data[\'source_hashes\']={}\n    for p in [Path(__file__),ROOT.parent/\'control_nucleo_etapa1/control_nucleo.py\',ROOT.parent/\'deltaE_nucleo_completo/calcular_deltaE.py\',ROOT.parents[1]/\'sources/BCH_Reconstruction_in_Quantum_NSF(2).pdf\',ROOT.parents[1]/\'upload/Quantum_scattering_II_revised_final(1).pdf\']:\n        if p.exists():data[\'source_hashes\'][str(p.relative_to(ROOT.parents[1]))]=hashlib.sha256(p.read_bytes()).hexdigest()\n    (ROOT/\'resultados_WFD.json\').write_text(json.dumps(data,indent=2)+\'\\n\')\n    print(json.dumps({\'volume_checks\':data[\'volume_scaling_errors\'],\'nonzero_example\':data[\'nonzero_merger\'][\'rows\'][0]},indent=2))\n\nif __name__==\'__main__\':main()\n', 'canal_23/deltaE_nucleo_completo/calcular_deltaE.py': '"""Complete quadratic angular source on the support of Bondi Eq.(88).\n\nNot an implementation of the NSF kernel at arbitrary momenta. It evaluates\nALL five source blocks needed at the two exactly collinear exchange vertices.\nExact angular local deltas are retained; all nonlocal Green functions, including\nthe outgoing helicity projection, are regularized by the SAME heat filter.\nNo prior candidate-kernel code, conditional nu0 completion, or energy delta used.\n\nDependencies: numpy, scipy. Run: python3 calcular_deltaE.py\nThe target is the externally connected diagonal coefficient at epsilon^2,\nNOT the full expectation including spectators or the order-epsilon^4 UV density.\n"""\nimport itertools,json,hashlib\nfrom pathlib import Path\nimport numpy as np\nfrom scipy.special import eval_jacobi\nfrom numpy.polynomial.legendre import leggauss\n\nBLOCKS=[\'Omega_contact\',\'Omega_affine\',\'Lambda_bilocal\',\'Lambda_local_1\',\'Lambda_local_2\']\n\ndef greens(x,L):\n    """R22(x), its first two x derivatives, and R20(x).\n\n    G00_l=(2l+1)/(4pi [(l-1)l(l+1)(l+2)]).\n    G22 = sum (2l+1)/(4pi) heat X^2 P_(l-2)^(4,0)(x), X=(1-x)/2.\n    G20 = sum G00_l heat P_l^2(x), with its e^(2ih phi) phase separate.\n    These follow by differentiating the scalar Green, NOT choosing a pole value\n    of its unregularized directional quotient.\n    """\n    x=np.asarray(x,float);X=(1-x)/2\n    S=np.zeros_like(x);Sp=np.zeros_like(x);Spp=np.zeros_like(x);R20=np.zeros_like(x)\n    for ell in range(2,L+1):\n        n=ell-2;coef=(2*ell+1)/(4*np.pi)*np.exp(-16*ell*(ell+1)/L**2)\n        S+=coef*eval_jacobi(n,4,0,x)\n        if n>=1:Sp+=coef*(n+5)/2*eval_jacobi(n-1,5,1,x)\n        if n>=2:Spp+=coef*(n+5)*(n+6)/4*eval_jacobi(n-2,6,2,x)\n        lam=(ell-1)*ell*(ell+1)*(ell+2)\n        P2=(1-x*x)*(ell+1)*(ell+2)/4*eval_jacobi(n,2,2,x)\n        R20+=coef/lam*P2\n    return X*X*S,-X*S+X*X*Sp,.5*S-2*X*Sp+X*X*Spp,R20\n\ndef prod(a,b):\n    return (a[0]*b[0],a[1]*b[0]+a[0]*b[1],a[2]*b[0]+2*a[1]*b[1]+a[0]*b[2])\n\ndef lap(y,x,m):\n    return (1-x*x)*y[2]-2*x*y[1]-m*m/(1-x*x)*y[0]\n\ndef run(L,nx=None,nphi=32,shift=.137,p=1.,q=.5,s=.5):\n    assert abs(p-q-s)<1e-14 and min(p,q,s)>0\n    nx=nx or 6*L+24\n    x,wx=leggauss(nx);phi=2*np.pi*np.arange(nphi)/nphi+shift\n    R,Rp,Rpp,G20=greens(x,L);R2,Rp2,Rpp2,_=greens(-x,L)\n    h=prod((R,Rp,Rpp),(R2,-Rp2,Rpp2))\n    E=p+q;D=(E-s*x)/np.sqrt(2)\n    C=(p*q/2*(1-x*x),-p*q*x,np.full_like(x,-p*q))\n    invD2=(1/D**2,np.sqrt(2)*s/D**3,3*s*s/D**4)\n    affine=prod(prod(C,C),invD2)\n    csource=prod(C,h);asource=prod(affine,h)\n    dot=2*p*q;common=-1j*(E-s)/(2*np.pi*np.sqrt(2)*s)\n    grid_weight=wx[:,None]*2*np.pi/nphi\n    records=[]\n    for hout,hu,hv in itertools.product((2,-2),repeat=3):\n        f=(G20/D)[:,None]*np.exp(1j*hout*phi)[None,:]\n        # Actual complete source, including the two different internal spin phases.\n        mixed=hu!=hv\n        m=-hu+hv\n        phase=np.exp(1j*m*phi)[None,:]\n        vals=np.zeros(5,complex);abs_integrals=np.zeros(3);radial_pref=np.zeros(3,complex)\n        if mixed:\n            sources=[2*lap(csource,x,m),2*lap(asource,x,m),dot*h[0]]\n            for j,src in enumerate(sources):\n                integrand=.5*common*f*src[:,None]*phase\n                vals[j]=np.sum(grid_weight*integrand)\n                abs_integrals[j]=np.sum(grid_weight*abs(integrand))\n                radial_pref[j]=.5*common*np.sum(wx*G20/D*src)\n        # Exact local source deltas in B42, NOT dropped as generic fixed-leg terms.\n        # A smooth spectral eth^2 G00 has P_l^2(+/-1)=0 mode by mode.\n        _,_,_,ext_at_poles=greens(np.array([1.,-1.]),L)\n        pair=greens(np.array([-1.]),L)[0][0]\n        if hu==hv:\n            vals[3]=.5*common*dot*ext_at_poles[0]/((E-s)/np.sqrt(2))*pair\n            vals[4]=.5*common*dot*ext_at_poles[1]/((E+s)/np.sqrt(2))*pair\n        total=vals.sum()\n        records.append({\'hout\':hout,\'hu\':hu,\'hv\':hv,\'axial_weight\':hout-hu+hv,\n            \'blocks_re_im\':np.stack([vals.real,vals.imag],axis=-1).tolist(),\n            \'geometric_kernel_re_im\':[float(total.real),float(total.imag)],\n            \'kernel_abs\':float(abs(total)),\n            \'radial_prefactors_re_im\':np.stack([radial_pref.real,radial_pref.imag],axis=-1).tolist(),\n            \'absolute_integrals_nonlocal_blocks\':abs_integrals.tolist()})\n    return {\'L\':L,\'nx\':nx,\'nphi\':nphi,\'azimuth_shift\':shift,\n            \'momenta_in_own_axis\':[s,p,-q], \'source_energy\':E,\'output_energy\':s,\n            \'vertex_energy_difference\':s-E,\'rows\':records,\n            \'max_kernel_abs\':max(v[\'kernel_abs\'] for v in records),\n            \'local_terms_retained\':True,\n            \'local_projection_mode_by_mode_zero\':bool(np.all(ext_at_poles==0))}\n\ndef checks():\n    # Independent verification that differentiated Jacobi sums match finite differences.\n    x=np.array([-.63,-.17,.24,.69]);eps=2e-5\n    r,rp,rpp,g=greens(x,24)\n    plus=greens(x+eps,24)[0];minus=greens(x-eps,24)[0]\n    d1=float(np.max(abs((plus-minus)/(2*eps)-rp)))\n    d2=float(np.max(abs((plus-2*r+minus)/eps**2-rpp)))\n    assert d1<1e-6 and d2<1e-4,(d1,d2)\n    # Independent tensor-dyad phase: G22 to north has +2phi, to south -2phi.\n    ph=np.array([.23,.71,1.22]);xx=.37;ss=np.sqrt(1-xx*xx)\n    nn=np.stack([ss*np.cos(ph),ss*np.sin(ph),np.full_like(ph,xx)],-1)\n    mm=np.stack([xx*np.cos(ph)-1j*np.sin(ph),xx*np.sin(ph)+1j*np.cos(ph),np.full_like(ph,-ss)],-1)/np.sqrt(2)\n    errors=[]\n    for direction,mp,sgn in [(np.array([0,0,1]),np.array([1,1j,0])/np.sqrt(2),1),\n                              (np.array([0,0,-1]),np.array([-1,1j,0])/np.sqrt(2),-1)]:\n        X=(1-nn@direction)/2\n        A=-(mm@direction)/np.sqrt(2);B=-(nn@mp)/np.sqrt(2);C=-(mm@mp)\n        num=(A*B-X*C)**2;phase=num/abs(num)\n        errors.append(float(np.max(abs(phase-np.exp(2j*sgn*ph)))))\n    assert max(errors)<1e-12\n    # Outgoing differentiated Green tends to B24 derivative away from coincidence.\n    x0=np.array([-.65,-.2,.25,.65]);closed=(1+x0)/(8*np.pi)\n    convergence=[]\n    for L in [32,64,128,256]:\n        val=greens(x0,L)[3]\n        convergence.append({\'L\':L,\'G20_max_abs_difference_from_closed_away_from_poles\':float(max(abs(val-closed)))})\n    assert convergence[-1][\'G20_max_abs_difference_from_closed_away_from_poles\']<convergence[0][\'G20_max_abs_difference_from_closed_away_from_poles\']\n    return {\'radial_first_derivative_error\':d1,\'radial_second_derivative_error\':d2,\n            \'dyad_vs_spin_phase_errors\':errors,\'G20_convergence_checks\':convergence}\n\ndef finite_box_contractions(first,second,cell=1.):\n    """Direct Fock action of T1 on the retained collinear vertex support.\n\n    Canonical c oscillators are used internally. Part-I a=sqrt(omega/cell)c,\n    dmu=cell/(2omega), delta^3=Kronecker/cell. This gives the splitting\n    coefficient 4i sqrt(cell) kappa*/(8sqrt(omega_p omega_u omega_v)).\n    Kappa here is the stored GEOMETRIC coefficient, with mode prefactor one;\n    the residuals below are arithmetic controls, not physical DeltaE errors.\n    """\n    w=np.array([.5,.5,.5,.5,1.,1.,1.,1.]);vertices=[]\n    lookup=[]\n    for direction,run0 in enumerate((first,second)):\n        lut={(r[\'hout\'],r[\'hu\'],r[\'hv\']):complex(*r[\'geometric_kernel_re_im\']) for r in run0[\'rows\']}\n        lookup.append(lut)\n        for hp,hr,hv in itertools.product((2,-2),repeat=3):\n            parent=2*direction+int(hp<0);internal=4+2*direction+int(hr<0)\n            other=2*(1-direction)+int(hv<0)\n            gamma=1j*np.sqrt(cell)/(2*np.sqrt(w[parent]*w[internal]*w[other]))*lut[hp,hr,hv].conjugate()\n            vertices.append((parent,internal,other,gamma))\n    def act(occ):\n        out={}\n        for parent,internal,other,g in vertices:\n            for ops,value in [([(parent,False),(internal,True),(other,True)],g),\n                              ([(other,False),(internal,False),(parent,True)],g.conjugate())]:\n                ns=list(occ);z=value\n                for mode,create in ops:\n                    if create:z*=np.sqrt(ns[mode]+1);ns[mode]+=1\n                    elif ns[mode]>0:z*=np.sqrt(ns[mode]);ns[mode]-=1\n                    else:z=0;break\n                if z:out[tuple(ns)]=out.get(tuple(ns),0)+z\n        return out\n    def moments(occ):\n        psi=act(occ)\n        norm=sum(abs(z)**2 for z in psi.values())\n        energy=sum(float(np.dot(w,state))*abs(z)**2 for state,z in psi.items())\n        return norm,energy\n    result=[]\n    for h1,h2 in itertools.product((2,-2),repeat=2):\n        one=np.zeros(8,int);two=np.zeros(8,int)\n        one[int(h1<0)]=1;two[2+int(h2<0)]=1\n        N1,F1=moments(one);N2,F2=moments(two);N,F=moments(one+two)\n        W=N-N1-N2;FH=F-(F1+.5*N1)-(F2+.5*N2);D=FH-W\n        direct=cell*sum(abs(lookup[0][h1,hr,h2])**2+abs(lookup[1][h2,hr,h1])**2 for hr in (2,-2))\n        error=abs(D-direct)\n        assert error<1e-12*max(direct,1e-60),(D,direct,error)\n        result.append({\'incoming_helicities\':[h1,h2],\'cell_d3k\':cell,\n          \'Wconn_fock_geometric\':W,\'Fconn_fock_geometric\':FH,\'Dconn_fock_geometric\':D,\n          \'Dconn_direct_geometric\':direct,\'fock_vs_direct_error\':error})\n    return result\n\nif __name__==\'__main__\':\n    root=Path(__file__).resolve().parent\n    runs=[run(L) for L in [8,16,32,64,128,256]]\n    runs.extend([run(32,nx=2*(6*32+24),nphi=64,shift=.417),run(64,nphi=48,shift=.29)])\n    # Opposite exchange vertex uses its own oriented axis, and hu/hv/hout keep\n    # their physical helicities. Its eight coefficients are computed independently.\n    opposite=[run(L,shift=.531) for L in [16,64,256]]\n    tests=checks()\n    # Same-helicity first row is local and zero; use a mixed daughter row.\n    ra=np.array(runs[2][\'rows\'][1][\'radial_prefactors_re_im\'])\n    rb=np.array(runs[6][\'rows\'][1][\'radial_prefactors_re_im\'])\n    tests[\'nonzero_radial_integrals_grid_doubling_max_abs_difference\']=float(np.max(abs(ra-rb)))\n    assert tests[\'nonzero_radial_integrals_grid_doubling_max_abs_difference\']<1e-9\n    assert max(r[\'max_kernel_abs\'] for r in runs+opposite)<1e-10\n    data={\'target\':\'Delta E_conn at order epsilon^2, Bondi corrected Eq.(88)\',\n          \'source\':\'Complete B20-B43,B59,B71-B72 angular source from QS-I; cubic-generator convention from Bondi corrected Eq.(78)\',\n          \'kernel_validation_scope\':\'Complete five angular blocks on the two required exactly collinear exchange supports; not a globally validated arbitrary-momentum map\',\n          \'regulator\':\'All nonlocal scalar/spin Green projections use exp(-16 l(l+1)/L^2), with l<=L. Local source angular deltas exact; zero-frequency internal modes excluded.\',\n          \'normalization\':\'CCR omega delta^3, measure d3k/(2omega), H=2 int dmu omega a†a. Stored kernels are geometric B72 coefficients; any finite consistent mode prefactor multiplies zero. Numerical residuals are not physical Delta E error bars.\',\n          \'checks\':tests,\'exchange_1\':runs,\'exchange_2\':opposite,\n          \'finite_box_arithmetic_controls\':finite_box_contractions(runs[3],opposite[1])+finite_box_contractions(runs[3],opposite[1],8.),\n          \'connected_exact_result\':{\'W_conn\':0,\'F_conn\':0,\'D_conn\':0,\'DeltaE_conn_epsilon2_coefficient\':0},\n          \'full_expectation_including_spectators\':\'Not numerically evaluated by this support-specialized kernel.\',\n          \'not_imposed\':[\'Energy conservation at vertices\',\'Zero values of nonlocal integrands\',\'Arbitrary contact kernel\'],\n          \'limits\':\'This evaluates a rotationally covariant regulated prescription. It does not establish interchange of the collinear, packet and regulator limits.\'}\n    sources=[]\n    for name in [\'Quantum_scattering_I_revised(3).pdf\',\'Bondi_4_momentum_balance_PRD_BCH-1.pdf\']:\n        path=root.parents[1]/\'upload\'/name\n        if path.exists():sources.append({\'name\':name,\'sha256\':hashlib.sha256(path.read_bytes()).hexdigest()})\n    data[\'source_hashes\']=sources\n    (root/\'resultados_deltaE.json\').write_text(json.dumps(data,indent=2)+\'\\n\')\n    print(json.dumps({\'checks\':tests,\'runs\':[{\'L\':r[\'L\'],\'max_abs_kernel\':r[\'max_kernel_abs\']} for r in runs],\n        \'opposite\':[{\'L\':r[\'L\'],\'max_abs_kernel\':r[\'max_kernel_abs\']} for r in opposite],\n        \'finite_box_arithmetic_controls\':data[\'finite_box_arithmetic_controls\'],\n        \'connected_exact_result\':data[\'connected_exact_result\']},indent=2))\n', 'precision23/modelo_local.py': '"""Adaptador portable del mismo núcleo NSF. Unidades Ei=G=1."""\nimport os\nimport math\nimport numpy as np\nfrom scipy.special import roots_legendre\nfrom engine import ROOT\nimport momenta as m\nimport uv_spectator as uv\nimport polos_estable\nfrom motor_angulos import Kernel, exchange_parts\n_ORIGINAL={name:getattr(m,name) for name in [\'pa\',\'pc\',\'sample_a\',\'sample_c\',\'geometry\',\'density\']}\n\n\ndef evaluate23(task):\n    k, maximum, band, u, order, index, seed, fine = task\n    os.environ[\'FINE_POLAR_GRID\']=\'1\' if fine else \'0\'\n    os.environ[\'FUSED_INTEGRAND\']=\'0\'  # Python puro: no necesita compilador ni .so/.dll.\n    m.k=float(k);m.MAX=16. if band==\'low\' else float(maximum);m.A=m.MAX/2\n    m.L=np.log(m.A/m.k);m.T0=np.arctan((m.k-.5)/m.k);m.TZ=np.arctan((m.A-.5)/m.k)-m.T0\n    for name, fn in _ORIGINAL.items():setattr(m,name,fn)\n    if band==\'uv\':uv.LUV=np.log(m.A/uv.AMIN)\n    try:\n        row=m.run((np.asarray(u),order,index,seed)) if band==\'low\' else uv.run((np.asarray(u),order,index,seed))\n    finally:\n        polos_estable.DIAGNOSTICS.clear()\n    row.update(kappa=k,band=band,polar_mesh=\'refined\' if fine else \'base\',id=f\'{band}:{seed}:{index}\')\n    if not all(np.isfinite(row[t]) for t in [\'P\',\'Q\',\'E\']):\n        raise FloatingPointError(f\'Muestra no finita: {row["id"]}\')\n    return row\n\n\ndef quadrature22(k,maximum,order,ne,nq):\n    # Reciprocidad exacta: rho(E;k)=E^-4 rho(1/E;k/E).\n    # Se reúnen E=u y E=1/u; cada uno conserva su propio soporte [2k,maximum].\n    limit=max(maximum,1/(2*k))\n    values=[2024.,1.,1.2,1.5,2.,4.,8.,32.,128.,512.,maximum,8192.,1/(2*k),limit,1/(1-2*k)]\n    scale=k\n    while scale<1:values.append(1+scale);scale*=2\n    edges=sorted(set(v for v in values if 1<=v<=limit))\n    xe,we=roots_legendre(ne);xq,wq=roots_legendre(nq);tasks=[]\n    for segment,(lo,hi) in enumerate(zip(edges[:-1],edges[1:])):\n        for x,w in zip(xe,we):\n            zlo,zhi=np.log(lo),np.log(hi);u=np.exp(zlo+(x+1)/2*(zhi-zlo));ew=w/2*(zhi-zlo)*u\n            upper=u<=maximum;lower=u<1/(2*k)\n            if not (upper or lower):continue\n            q0=max(k,(u-1)/2);qc=max(k*u,(u-1)/2) if lower else q0;qmax=np.hypot(u,1)/2\n            # (Pcoef,Dcoef): D integra (Ef-1)P, para no restar dos integrales próximas.\n            pc=(1. if upper else 0.)+(u*u if lower else 0.)\n            dc=-(u-1)**2 if upper and lower else ((u-1) if upper else u*(1-u))\n            sections=[(qc,qmax,pc,dc)]\n            if upper and qc>q0*(1+1e-13):sections.append((q0,qc,1.,u-1))\n            for qa,qb,pc,dc in sections:\n                if qb<=qa:continue\n                za,zb=np.log(qa),np.log(qb)\n                qe=np.linspace(za,zb,max(1,int(np.ceil((zb-za)/np.log(4))))+1)\n                for zl,zh in zip(qe[:-1],qe[1:]):\n                    for xx,ww in zip(xq,wq):\n                        q=np.exp(zl+(xx+1)/2*(zh-zl));factor=ew*np.pi*u*q*q*ww/2*(zh-zl)\n                        tasks.append((float(u),float(q),order,float(factor*pc),float(factor*dc),segment,len(tasks)))\n    return tasks\n\n\ndef evaluate22(task):\n    u,q,order,wp,wd,segment,index=task\n    os.environ[\'FINE_POLAR_GRID\']=\'1\';os.environ[\'FUSED_INTEGRAND\']=\'0\'\n    mu=float(np.clip((u*u+1-4*q*q)/(2*u),0,1))\n    st=np.sqrt(max(0,(4*q*q-(u-1)**2)*((u+1)**2-4*q*q)))/(2*u)\n    norm=np.hypot(mu,st);mu/=norm;st/=norm\n    v=np.array([[0.,0.,.5],[0.,0.,-.5],[u/2*st,0.,u/2*mu],[-u/2*st,0.,-u/2*mu]])\n    try:\n        a=exchange_parts(v,Kernel(order))[\'iteration\']/(.25*u)\n        weight=float(np.sum(abs(a)**2)/4)\n    finally:\n        polos_estable.DIAGNOSTICS.clear()\n    if not np.isfinite(weight):raise FloatingPointError(f\'2->2 no finito, nodo {index}\')\n    return dict(id=str(index),index=index,u=u,q=q,order=order,segment=segment,weight=weight,P=wp*weight,D=wd*weight)\n', 'precision23/stable_geometry.py': '"""Canonical coordinates for nonzero, very small angles without subtracting projections.\nOnly coordinate construction uses long double. No angular region is excluded.\n"""\nimport numpy as np\nimport os\n\ndef canonical(pv,qv):\n    dtype=np.float64 if os.environ.get(\'NSF_GEOMETRY_DOUBLE\')==\'1\' else np.longdouble\n    a=np.asarray(pv,dtype);b=np.asarray(qv,dtype)\n    total=a+b;s=np.sqrt(np.sum(total*total))\n    if not s>0:raise ValueError(\'Zero parent momentum requires separate support\')\n    ez=total/s\n    # Cross products retain a tiny transverse component that p-(p.ez)ez can lose.\n    transverse=np.cross(ez,np.cross(a,ez));px=np.sqrt(np.sum(transverse*transverse))\n    if not px>0:raise ValueError(\'Exactly collinear support remains unassigned\')\n    ex=transverse/px;ey=np.cross(ez,ex)\n    pz=np.sum(a*ez);qz=np.sum(b*ez)\n    rot=np.asarray([ex,ey,ez],float)\n    u=np.array([float(px),0.,float(pz)]);v=np.array([-float(px),0.,float(qz)])\n    return float(s),u,v,rot\n'}

